WITH payload AS (SELECT $archive_payload$[{"id":"5f765cf7-6a9c-5403-be92-14e4b2d1b95e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -مطالبة الزوجة بنفقة ماضية -اليمن تشرع يف جانب أقوى املتداعين -احلكم بالنفقة املاضية.","document_number":"34181745","case_number":"33438695","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"نفقة -نفقة زوجة -مطالبة الزوجة بنفقة ماضية -اليمن تشرع يف جانب أقوى املتداعين -احلكم بالنفقة املاضية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/4/8 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34181745 :‬‬\n                         ‫َر ْق ُم الدعوى‪33438695 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34347399‬تاريخه‪1434/11/3 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬نفقــة زوجــة ‪ -‬مطالبــة الزوجــة بنفقــة ماضيــة ‪ -‬اليمــن تشــرع‬\n                                    ‫يف جانــب أقــوى املتداعيــن ‪ -‬احلكــم بالنفقــة املاضيــة‪.‬‬\n\n\n\n\n                                                           ‫‪ .1‬قوله تعالى { ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِت ِه }‬\n                                          ‫‪ .2‬قولــه تعالــى { َو َل ُهـ َّـن مِ ْثـ ُـل ا َّلــذِ ي َع َل ْيهِ ـ َّـن ِب ْالَ ْعـ ُـر ِ‬\n      ‫وف َولِل ِّر َجــالِ َع َل ْيهِ ـ َّـن‬\n                                                                                                                               ‫َد َر َجـ ٌة}‬\n      ‫‪ .3‬قولــه صلــى اهلل عليــه وســلم ( ولهــن عليكــم رزقهــن وكســوتهن‬\n                                                           ‫باملعــروف ) رواه مســلم‬\n      ‫‪ .4‬حديــث عائشــة رضــي اهلل عنهــا أن هنــد بــن عتبــة قالــت لرســول اهلل‬\n      ‫صلــى اهلل عليــه وســلم ‪ :‬إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي‬\n      ‫مــا يكفينــي وولــدي إال مــا أخــذت منــه وهــو ال يعلــم فقــال ( خــذي مــا‬\n                            ‫يكفيــك وولــدك باملعــروف) رواه البخــاري ومســلم‪.‬‬\n      ‫‪ .5‬مــا قــرر صاحــب الــروض املربــع ( يلــزم الــزوج نفقــة زوجتــه قوتـ ًا أي‬\n                             ‫خبــز ًا أو أدمـ ًا وكســوة وســكنى مبــا يصلــح ملثلهــا)‬\n                                       ‫‪ .6‬اليمني تشرع يف جانب أقوى املتداعيني‬\n\n\n\n\n‫‪137‬‬\n\f‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا وقــد صــدر حكــم‬\n‫مكتســب للقطعيــة بفســخ نكاحهــا وقــد خرجت عندمــا كانت زوجته‬\n‫بعــد أن قــام بطردهــا مــن منزلــه يف ‪1431/12/27‬ه ـ بعــد أن اعتــدى‬\n‫عليهــا بالضــرب ومت نقلهــا للمستشــفى وصــدر بحقهــا تقريــر طبــي ومنــذ‬\n‫خروجهــا وحتــى احلكــم بفســخ نكاحهــا يف ‪1432/11/28‬ه ـ لــم ينفــق‬\n‫املدعــى عليــه عليهــا وطالبــت املدعيــة إلــزام املدعــى عليــه بنفقتهــا مــن‬\n‫طردهــا وحتــى تاريــخ احلكــم بفســخ نكاحهــا ‪ -‬أجــاب املدعــى عليــه‬\n‫ا وقــرر أنــه لــم يطــرد املدعيــة‬       ‫باملصادقــة علــى الدعــوى جملــة وتفصي ـ ً‬\n‫ولكــن هــي مــن اتصلــت بأخيهــا فحضــر وأخذهــا وقــرر أنــه لــم ينفــق‬\n‫عليهــا طيلــة تلــك الفتــرة ‪ -‬أقــر املدعــى عليــه بضــرب املدعيــة ‪ -‬قــررت‬\n‫املدعيــة عــدم وجــود بينــة أن املدعــى عليــه قــام بطردهــا وقــرر ناظــر‬\n‫ـاء علــى إقــرار املدعــى عليــه بضربــه املدعيــة يف يــوم‬      ‫القضيــة أنــه بنـ ً‬\n‫كاف يف اعتبــاره‬        ‫ٍ‬       ‫محــل اخلــاف والضــرب قرينــة علــى الطــرد وهــو‬\n‫مبــرر ًا خلــروج املدعيــة‪ ،‬كمــا مت تقديــر النفقــة مــن قبــل هيئــة اخلبــراء‬\n‫باحملكمــة للفتــرة محــل اخلــاف لتكــون نفقــة شــهرية خمســمائة ريــال‬\n‫لتكــون كامــل املــدة خمســة آالف وخمســمائة ريــال‪ ،‬وحيــث إن اليمني‬\n‫تشــرع يف جانــب أقــوى املتداعــن لــذا ‪ -‬جــرى عرض اليمــن على املدعية‬\n‫علــى صحــة دعواهــا فاســتعدت بأدائهــا وحلفــت علــى صحــة دعواهــا ‪-‬‬\n‫وملــا قــرره ناظــر القضيــة يف أســباب احلكــم ولقولــه تعالــى { ل ُِي ْنفِ ـ ْـق ُذو‬\n‫َسـ َـع ٍة مِ ــنْ َسـ َـع ِت ِه } فقــد صــدر احلكــم علــى املدعــى عليــه بــأن يســلم‬\n‫املدعيــة النفقــة املاضيــة مــن تاريــخ طردهــا وحتــى تاريــخ احلكــم بفســخ‬\n\n                                                                                            ‫‪138‬‬\n\f      ‫نكاحهــا مبلغ ـ ًا وقــدره خمســة آالف وخمســمائة ريــال وقنعــت املدعيــة‬\n      ‫وقــرر املدعــى عليــه املعارضــة وصــدر قــرار محكمــة االســتئناف مبكــة‬\n                                           ‫املكرمــة باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33438695‬وتاريــخ‬\n      ‫‪1433/07/01‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331236545‬وتاريــخ‬\n      ‫‪1433/07/01‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/08/24‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 02 : 00‬وفيهــا حضــرت فلســطينية اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم واملعــرف بهــا مــن قبــل شــقيقها فلســطيني اجلنســية بوثيقــة‬\n      ‫مصريــة مبوجــب اإلقامــة رقــم وادعــت علــى احلاضــر معهــا فلســطيني‬\n      ‫اجلنســية بوثيقــة مصريــة مبوجــب اإلقامــة رقــم قائلــة ‪ :‬إن املدعــى عليــه‬\n      ‫كان زوجــا لــي وقــد صــدر حكــم من هذه احملكمــة برقم ‪32341375‬‬\n      ‫وتاريــخ ‪1432/11/28‬ه ـ واملصــدق مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 33219874‬وتاريــخ ‪1433/4/28‬ه ـ يقضــي بفســخ نكاحــي منه ‪ ،‬وقد‬\n      ‫أجنبــت منــه علــى فــراش الزوجيــة أوالدا هــم ‪ ......‬مــن مواليــد ‪1421‬ه ـ‬\n      ‫و‪ .....‬مــن مواليــد ‪1423‬ه ـ و‪ .....‬مــن مواليــد ‪1426‬ه ـ ‪ ،‬وقــد خرجــت مــن‬\n      ‫بيــت املدعــى عليــه بعــد أن قــام بطــردي مــن منزلــه يف ‪1431/12/27‬ه ـ‬\n      ‫بعــد أن اعتــدى علــي بالضــرب‪ ،‬ومت نقلــي ملستشــفى ‪ ....‬وصــدر بحقــي‬\n      ‫تقريــر طبــي مبدئــي بتاريــخ ‪1431/12/27‬ه ـ املتضمــن أن ظــروف‬\n      ‫اإلصابــة ادعــاء مضاربــة وعنــف أســري ‪ ،‬ومنــذ ذلــك التاريــخ وحتــى‬\n\n‫‪139‬‬\n\f‫احلكــم بفســخ النــكاح يف ‪ 1432/11/28‬لــم ينفــق املدعــى عليــه علــي‪،‬‬\n‫أطلــب إلزامــه بدفــع نفقتــي طيلــة تلــك الفتــرة ‪ .‬هــذه دعــواي ‪ .‬ثــم أبــرزت‬\n‫املدعيــة الصــك املشــار إليــه وصــورة مــن التقريــر الطبــي ‪ ،‬ومت تزويــد‬\n‫أوراق املعاملــة بــه ‪ ،‬وبعرضــه علــى املدعــى عليــه قــال ‪ :‬إن مــا ذكرتــه‬\n‫املدعيــة مــن الــزواج والفســخ واإلجنــاب والعنــف األســري فصحيــح ‪،‬‬\n‫ولكننــي لــم أطــرد املدعيــة مــن املنــزل بــل هــي مــن اتصلــت بأخيهــا‬\n‫فحضــر وأخذهــا ‪ ،‬ولــم انفــق عليهــا طيلــة تلــك الفتــرة ‪ .‬وبعــرض ذلــك‬\n‫علــى املدعيــة قالــت ‪ :‬بــل أخرجنــي مــن البيــت ‪ ،‬ومكثــت نصــف ســاعة‬\n‫أمــام العمــارة حتــى وصلــت الشــرطة ‪ ،‬فســألني الضابــط عــن زوجــي‬\n‫فأخبرتــه أنــه يف الشــقة ‪ ،‬فقــام الضابــط باقتيــاده ملركــز الشــرطة ‪،‬‬\n‫ومت إيقافــه ‪ ،‬وحينهــا اتصلــت علــى أخــي ليكــون أحــد محارمــي معــي ‪.‬‬\n‫وبعــرض ذلــك علــى املدعــى عليــه قالــت ‪ :‬بــل هــي مــن خرجــت ‪ .‬وبطلــب‬\n‫البينــة مــن املدعيــة علــى ذلــك قالــت ‪ :‬أطلــب اإلمهــال مــن أجــل ذلــك ‪.‬‬\n‫ثــم قــررت الكتابــة لقســم اخلبــراء لتقديــر النفقــة املاضيــة مــن تاريــخ‬\n‫‪1431/12/27‬ه ـ وحتــى تاريــخ ‪1432/11/28‬ه ـ ‪ .‬ثــم رفعــت اجللســة‬\n‫لذلك ‪ .‬ويف يوم األحد املوافق ‪1434/03/08‬هـ افتتحت اجللسة الساعة‬\n‫‪ 08 : 30‬وفيهــا حضــرت املدعيــة واملعــرف بهــا شــقيقها ‪ ،‬ولــم يحضــر‬\n‫املدعــى عليــه وال مــن ميثلــه ‪ ،‬وقــد وردنــا التبليــغ مــن قســم احملضريــن‬\n‫مفــاده (مت االنتقــال للموقــع وال يوجــد أحــد باملنــزل ومت االتصــال علــى‬\n‫جوالــه ومت تبليغــه هاتفيــا وأفــاد بأنــه علــم باملوعــد) بنــاء علــى املــادة ‪55‬‬\n‫مــن نظــام املرافعــات الشــرعية فقــد قــررت الســير يف الدعــوى غيابيــا‬\n‫يف حــق املدعــى عليــه ‪ ،‬وبســؤال املدعيــة عمــا طلبــت اإلمهــال مــن أجلــه‬\n‫قالــت ‪ :‬ليــس لــدي ســوى التقريــر الطبــي ومحضــر شــرطة الســامة‬\n\n\n                                                                                         ‫‪140‬‬\n\f      ‫والــذي مت تدويــن تلــك الوقائــع فيــه ‪ ،‬وأطلــب مخاطبــة فضيلــة القاضــي‬\n      ‫‪ ..........‬لتزويدكــم نســخة مــن ذلــك احملضــر ‪ .‬وقــد وردتنــا املعاملــة مــن‬\n      ‫قســم الصلــح بخطــاب رئيســها رقــم ‪ 331236545‬وتاريــخ ‪1434/2/4‬هـ‬\n      ‫ومرفــق بــه محضــر اللجنــة ‪ ،‬ونصــه (حضــر الطرفــان وحســب توجيــه‬\n      ‫فضيلتكــم بتقديــر النفقــة مــن ‪1431/12/27‬ه ـ إلــى ‪1432/11/27‬ه ـ‬\n      ‫للمدعيــة ‪ ..........‬وعليــه فإننــا نــرى أن تكــون النفقــة الشــهرية خمســمائة‬\n      ‫ريــال للفتــرة احملــددة وهــي أحــد عشــر شــهرا لــكل شــهر خمســمائة‬\n      ‫ريــال ليكــون املبلــغ كامــا خمســة آالف وخمســمائة ريــال لكامــل‬\n      ‫املــدة والــرأي لفضيلتكــم) وبعرضــه علــى املدعيــة وافقــت عليــه ‪ .‬ثــم‬\n                                                               ‫رفعــت اجللســة لذلــك ‪.‬‬\n      ‫ويف يــوم االثنــن املوافــق ‪1434/04/08‬ه ـ افتتحــت اجللســة الســاعة ‪00‬‬\n      ‫‪ 08 :‬وفيهــا حضــرت املدعيــة ‪ ..........‬واملعــرف بهــا شــقيقها واملدعــى‬\n      ‫عليــه‪ ،‬وبعــرض مــا قــرره أعضــاء جلنــة الصلــح علــى املدعــى عليــه‬\n      ‫قــال ‪ :‬لــم أطــرد املدعيــة ‪ ،‬بــل هــي مــن خرجــت مــن البيــت ‪ .‬وأبــرزت‬\n      ‫املدعيــة صــورة محضــر تنفيــذ مهمــة وتســليمها جلهــة االختصــاص برقــم‬\n      ‫‪99/66161‬د يف ‪1431/12/27‬ه ـ مــن شــرطة قســم ‪ ..........‬مكــون مــن‬\n      ‫صفحتــن ‪ ،‬بخصــوص خــاف عائلــي ‪ ،‬كمــا أبــرزت صــورة مــن تقريــر‬\n      ‫طبــي مبدئــي بتاريــخ ‪1431/12/27‬ه ـ املتضمــن أن ظــروف اإلصابــة‬\n      ‫ادعــاء مضاربــة (عنــف أســري) ‪ ،‬ومت إرفاقهمــا باملعاملــة ‪ ،‬وبعرضــه‬\n      ‫علــى املدعــى عليــه قــال ‪ :‬إننــي يف ذلــك اليــوم لــم أطردهــا مــن املنــزل‬\n      ‫بــل هــي مــن خرجــت ‪ ،‬وأمــا ضربــي لهــا فصحيــح ‪ ،‬وكان ذلــك بســبب‬\n      ‫تلفــظ املدعيــة بألفــاظ شــتم وســب ألهلــي ‪ .‬وبعرضــه علــى املدعيــة قالــت‬\n      ‫‪ :‬ليــس لــدي بينــة ‪ .‬وبســؤال املدعيــة اليمــن علــى صحــة دعواهــا يف‬\n\n\n‫‪141‬‬\n\f‫طــرد املدعــى عليــه لهــا ذلــك اليــوم محــل اخلــاف يف ‪1431/12/27‬هــ‪،‬‬\n‫اســتعدت لذلــك ‪ ،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أن املدعــى عليــه هــو مــن طردنــي مــن بيتــه يــوم اجلمعــة املوافــق‬\n‫‪1431/12/27‬ه ـ بعــد ضربــه لــي ‪ ،‬وقــد مكثــت يف الشــارع حوالــي‬\n‫نصــف ســاعة ‪ ،‬وقــد اتصلــت بالشــرطة وبأخــي هــذا احلاضــر معــي ‪،‬‬\n‫وحضــر أخــي وحضــرت الشــرطة ومت إعــداد محضــر بالواقعــة ‪ .‬هكــذا‬\n‫حلفــت ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ ،‬وبنــاء علــى مــا‬\n‫قــرره أعضــاء جلنــة الصلــح ‪ ،‬وبنــاء علــى إقــرار املدعــى عليــه بضــرب‬\n‫املدعيــة ذلــك اليــوم محــل اخلــاف يف ‪1431/12/27‬ه ـ ‪ ،‬وإنــكاره‬\n‫لطــرد املدعيــة مــن البيــت ‪ ،‬ومبــا أن املدعيــة لــم تقــم البينــة علــى قيــام‬\n‫املدعــى عليــه بطردهــا ‪ ،‬إال أن الضــرب قرينــة علــى ذلــك ‪ ،‬وهــو كاف‬\n‫يف اعتبــاره مبــررا خلــروج املدعيــة مــن البيــت ‪ ،‬ومبــا أن اليمــن تشــرع يف‬\n‫جانــب أقــوى املتداعيــان كمــا قــرر ذلــك أهــل العلــم ‪ ،‬ومبــا أن جانــب‬\n‫املدعيــة قــد ترجــح قوتــه ‪ ،‬وبنــاء علــى ميــن املدعيــة علــى صحــة دعواهــا‬\n‫فيمــا يتعلــق بطــرد املدعــى عليــه لهــا ذلــك اليــوم محــل اخلــاف ‪ ،‬وبنــاء‬\n‫علــى إقــرار املدعــى عليــه بعــدم اإلنفــاق علــى املدعيــة طيلــة تلــك الفتــرة‬\n‫محــل الدعــوى ‪ ،‬ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته) ولقولــه تعالى‬\n‫(ولهــن مثــل الــذي عليهــن باملعــروف) ‪ ،‬وحلديــث (ولهــن عليكــم رزقهــن‬\n‫وكســوتهن باملعــروف) رواه مســلم وغيــره ‪ ،‬وحلديــث عائشــة رضــي اهلل‬\n‫عنهــا ‪ :‬أن هنــد بنــت عتبــة قالــت لرســول اهلل صلــى اهلل عليــه وســلم ‪:‬‬\n‫إن أبــا ســفيان رجــل شــحيح ‪ ،‬وليــس يعطينــي مــا يكفينــي وولــدي إال‬\n‫مــا أخــذت منــه ‪ ،‬وهــو ال يعلــم ‪ ،‬فقــال ‪( :‬خــذي مــا يكفيــك وولــدك‬\n‫باملعــروف) رواه البخــاري ومســلم وغيرهمــا ‪ ،‬وملــا قــرره أهــل العلــم مــن‬\n\n\n                                                                                       ‫‪142‬‬\n\f      ‫وجــوب اإلنفــاق مــن الــزوج علــى زوجتــه مبــا يصلــح ملثلهــا ‪ ،‬ومــن ذلــك‬\n      ‫مــا قــرره صاحــب الــروض املربــع ونصــه ‪( :‬يلــزم الــزوج نفقــه زوجتــه‬\n      ‫قوتــا أي خبــزا و أدمــا وكســوة وســكنى مبــا يصلــح ملثلهــا) ‪ ،‬لذلــك‬\n      ‫كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه بدفــع مبلــغ قــدره خمســة‬\n      ‫آالف وخمســمائة ريــال للمدعيــة‪ .‬وبــه قنعــت املدعيــة ‪ ،‬وقــرر املدعــى‬\n      ‫عليــه االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم وإفهامــه بــأن‬\n      ‫لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف‬\n      ‫االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة ‪30‬‬\n      ‫‪ . 08 :‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف ‪1434/04/08‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم الثالثــاء املوافــق‪ 1434/11/18‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 1 : 15‬وفيهــا قــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف بخطــاب رئيســها رقــم ‪ 331236545‬وتاريــخ ‪1434/11/9‬ه ـ‬\n      ‫وبالقــرار رقــم ‪ 34347399‬وتاريــخ ‪1434/11/3‬ه ـ ومضمونــه مــا يلــي (‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثرية‬\n      ‫املوافقــة علــى احلكــم ) ‪ .‬وحتــى ال يخفــى جــرى أثباتــه وأقفلــت اجللســة‬\n      ‫الســاعة ‪ 1 : 20‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/18‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية‬\n      ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪143‬‬\n\f‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 331236545‬وتاريــخ‬\n‫‪1434/10/19‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪....‬‬\n‫القاضــي باحملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34181745‬وتاريــخ‬\n‫‪1434/4/8‬هــ‪ ،‬املتضمــن دعــوى املــرأة (‪ )........‬فلســطينية اجلنســية ضــد‬\n‫(‪ ).....‬فلســطيني اجلنســية يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n     ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                ‫‪144‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":137,"source_page_end":144,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c2a197dc304f192f1c2d45bf224cac366f87bc5b75e4ee1661a7a058d8942b32","normalized_text_hash":"b36f5f14548b9bf7a6267a19d805ceff74a26afd86b0e31c8711d37d1bda385c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p137-34181745"},{"id":"4ef5ba75-66df-5ee2-8310-62940fcf7060","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -طلب زيادة النفقة لكبر األوالد -طلب زيادة النفقة لزيادة راتب األب -طلب تسديد رسوم الدراسة -طلب توفير سيارة وسائق لأوالد -إثبات الصلح واحلكم مبوجبه -رفض أحد املتصاحلن التوقيع وتقريره عدم القناعة -تدوين رفض االلتماس يف ضبط القضية -التهميش على الصك بتنفيذ بعض بنود احلكم.","document_number":"33461612","case_number":"26890105","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/21","year":"1434","subject":"نفقة -طلب زيادة النفقة لكبر األوالد -طلب زيادة النفقة لزيادة راتب األب -طلب تسديد رسوم الدراسة -طلب توفير سيارة وسائق لأوالد -إثبات الصلح واحلكم مبوجبه -رفض أحد املتصاحلن التوقيع وتقريره عدم القناعة -تدوين رفض االلتماس يف ضبط القضية -التهميش على الصك بتنفيذ بعض بنود احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/21 :‬هـ‬\n                        ‫ُ‬                 ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪33461612 :‬‬\n                           ‫َر ْق ُم الدعوى‪26890105 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 3417309‬تاريخه‪1434/1/230 :‬هـ‬\n\n\n\n        ‫نفقــة ‪ -‬طلــب زيــادة النفقــة لكبــر األوالد ‪ -‬طلــب زيــادة النفقــة لزيــادة‬\n        ‫راتــب األب ‪ -‬طلــب تســديد رســوم الدراســة ‪ -‬طلــب توفيــر ســيارة وســائق‬\n        ‫لــأوالد ‪ -‬إثبــات الصلــح واحلكــم مبوجبــه ‪ -‬رفــض أحــد املتصاحلــن‬\n        ‫التوقيــع وتقريــره عــدم القناعــة ‪ -‬تدويــن رفــض االلتمــاس يف ضبــط‬\n              ‫القضيــة ‪ -‬التهميــش علــى الصــك بتنفيــذ بعــض بنــود احلكــم‪.‬‬\n\n\n\n\n                                                ‫‪ -1‬قولة تعالى ( والصلح خير)‬\n                     ‫‪ -2‬قوله صلى اهلل عليه وسلم ( الصلح جائز بني املسلمني )‬\n                                          ‫‪ -3‬القاعدة الفقهية ال ضرر وال ضرار‬\n                                             ‫‪ -4‬القاعدة الفقهية ‪ :‬الضرر يزال‬\n                                        ‫‪ -5‬املادة ‪ 68‬من نظام املرافعات الشرعية‬\n        ‫‪ -6‬الالئحــة ‪ 3‬مــن املــادة ‪ 195‬مــن نظــام املرافعــات الشــرعية والئحتــه‬\n                                                                         ‫التنفيذيــة‬\n\n\n\n\n        ‫ادعــى وكيــل املدعيــة بــأن موكلتــه كانــت زوجــة للمدعى عليــه أصالة‬\n        ‫ثــم طلقهــا ورزقــت منــه بســبعة أوالد‪ -‬ذكــر أســماءهم وأعمارهــم‪-‬‬\n        ‫األوالد يف حضانــة أمهــم ويدرســون يف مــدارس خاصــة‪ -‬ســبق للجنــة‬\n\n‫‪145‬‬\n\f‫اإلصــاح يف احملكمــة تقديــر النفقــة الشــهرية‪ -‬توقــف املدعــى عليــه‬\n‫عــن النفقــة مــن أول شــهر شــوال ‪1431‬هــ‪ -‬لكبــر ســن األوالد وزيــادة‬\n‫مصاريفهــم ولزيــادة راتــب والدهــم املدعى عليه وألن املدعى عليه أصبح‬\n‫ميلــك ثــاث عمائــر‪ -‬طلــب املدعــي وكالــة نفقــة شــهرية جاريــة لــأوالد‬\n‫للمــأكل وامللبــس والعــاج حســبما يقــدره القاضــي ألن التقديــر الســابق‬\n‫ـداء مــن أول شــهر شــوال ‪1431‬هــ‪ -‬إلــزام املدعــى‬    ‫ال يكفــي وذلــك ابتـ ً‬\n‫عليــه بــأن يدفــع للمدعيــة رســوم الدراســة التــي دفعتهــا وذكــر قدرهــا‪-‬‬\n‫وإلزامــه بتســجيل االبــن الصغيــر باملدرســة‪ -‬إلــزام املدعــى عليه بتســديد‬\n‫الرســوم الدراســية لــأوالد للعــام احلالــي واألعــوام القادمة‪ -‬توفير ســيارة‬\n‫وســائق‪ -‬أجــاب املدعــى عليــه وكالــة بــأن الدعــوى غيــر صحيحــة جملــة‬\n‫وتفصي ـاً‪ -‬وســوف يحضــر البينــة علــى مصاريــف الدراســة‪ -‬يف جلســة‬\n‫قادمــة حضــرت املدعيــة أصالــة برفقــة أخيهــا كمــا حضــر املدعــى‬\n‫عليــه أصالــة برفقــة وكيلــه‪ -‬بعــرض الصلــح عليهمــا وتذكيرهمــا‬\n‫بــأن الشــقاق وكثــرة احملاكمــات يؤثــر ســلب ًا علــى األوالد ومســتقبلهم‬\n‫رغبــا يف الصلــح علــى مــا يلــي ‪ :‬أوال‪ :‬يدفــع املدعــى عليــه نفقــة شــهرية‬\n‫لــكل األوالد ( ذكــر مقدارهــا ) تســتقطع يف اليــوم األول مــن كل‬\n‫شــهر ميــادي مــن حســاب املدعــى عليــه الــى حســاب املدعيــة ثانيـ ًا يدفــع‬\n‫املدعــى عليــه مبلغ ـ ًا ذكــر مقــداره عــن النفقــة املاضيــة لــأوالد التــي‬\n‫دفعتهــا املدعيــة ثالثــا ‪ :‬يدفــع املدعــى عليــه مبلغـ ًا وقــدره (‪ )39.400‬ريــال‬\n‫للمدعيــة عــن قيمــة األقســاط الدراســية التــي دفعتهــا املدعيــه‪ -‬لقولــة‬\n‫تعالــى ( والصلــح خيــر ) وقولــة صلــى اهلل عليــه وســلم ( الصلــح جائــز‬\n‫بــن املســلمني ) جــرى إجــازة هــذا الصلــح واحلكــم بصحتــه ولزومــه‪-‬‬\n‫بعــد توقيــع املدعيــة ووكيلهــا واملعــرف ومغادرتهــم رفــض املدعــى عليــه‬\n\n\n                                                                                       ‫‪146‬‬\n\f      ‫ووكيلــه التوقيــع وقــرر عــدم القناعــة باحلكــم‪ -‬بنــاء علــى املــادة ‪68‬‬\n      ‫مــن نظــام املرافعــات الشــرعية جــرى إفهــام املدعــى عليــه بــأن لــه حــق‬\n      ‫االعتــراض‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪ -‬قــدم املدعــى‬\n      ‫عليــه التماسـ ًا حملكمــة االســتئناف ومت رفــض االلتمــاس‪ -‬مت التهميــش‬\n                                ‫علــى صــك احلكــم بتنفيــذ البنــد الثانــي والثالــث‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة‪/‬‬\n      ‫املســاعد برقــم ‪ 26890105‬وتاريــخ ‪ 1432/02/01‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 329389‬وتاريــخ ‪ 1432/02/01‬ه ـ ‪ .‬ويف هــذا اليــوم‬\n      ‫الســبت املوافق‪1433/06/21‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 00‬‬\n      ‫وفيهــا حضــر املدعــي وكالــة ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪...‬بوكالتــه عــن ‪ ...‬رقــم ‪ 51088‬يف ‪1433/06/08‬ه ـ اجللــد‬\n      ‫‪ 11794‬الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة كون‬\n      ‫ا عــن ‪...‬بالوكالــة رقــم ‪ 38219‬يف ‪1431/04/25‬ه ـ‬         ‫‪...‬املذكــور وكيـ ً‬\n      ‫جلــد ‪ 9529‬الصــادرة مــن كتابــة عــدل الثانيــة شــمال محافظــة جــدة‬\n      ‫املخولــه لــه حــق املرافعــة واملدافعــة وحضــور اجللســات وحضــر حلضــوره‬\n      ‫املدعــى عليــه أصالــه ‪...‬بالســجل املدنــي رقــم ‪...‬واملدعــى عليــه وكالــة‬\n      ‫‪...‬بالســجل املدني رقم ‪...‬بوكالته عن ‪...‬رقم ‪ 53982‬يف ‪1433/06/17‬‬\n      ‫اجللــد ‪ 11823‬الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n      ‫املخولــة لــه حــق املرافعــة واملدافعــة وحضــور اجللســات واالجابــة وادعــى‬\n\n‫‪147‬‬\n\f‫ا يف دعــواه (( املدعيــة كانــت زوجــة املدعــى عليــه‬   ‫املدعــي وكالــة قائـ ً‬\n‫ثــم طلقهــا وقــد رزقــت منــه علــى فــراش الزوجيــة الصحيحــة بســبعة‬\n‫أوالد وهــم‪... :‬وتاريــخ ميــاده ‪1418/08/21‬هــ‪ ،‬و‪...‬وتاريــخ ميالدهــا‬\n‫‪1420/06/18‬هــ‪ ،‬و‪ ...‬وتاريــخ ميالدهــا ‪1422/04/17‬هــ‪ ،‬و‪...‬وتاريــخ‬\n‫ميــاده ‪1423/08/23‬هــ‪ ،‬و‪ ...‬وتاريــخ ميــاده ‪1425/04/29‬هــ‪ ،‬و‪...‬‬\n‫وتاريخ ميالده ‪1426/08/19‬هـ‪ ،‬و‪ ...‬وتاريخ ميالدها ‪1428/11/23‬هـ‪.‬‬\n‫وهــم بيــد املدعيــة للحضانــة وهــم فقــراء ليــس لهــم مــال خــاص بهــم‬\n‫ووالدهــم ميســور احلــال فقــد كان يعمــل ‪ ،.......‬وميلــك ثــاث عمائــر‬\n‫بجــدة منهــا عمــارة بحــي الشــرفية بجــدة حتتــوي علــى عشــرين شــقة‬\n‫مؤجــرة‪ .‬علم ـ ًا بــأن األوالد يدرســون مبــدارس ‪ ...‬ويحتاجــون إلــى رســوم‬\n‫ومصاريــف دراســية باإلضافــة إلــى أجــرة املســكن وتكاليــف املعيشــة‬\n‫علــى أن يكســوهم ويتكفــل بعالجهــم باملعــروف‪ .‬وقــد كان ينفــق‬\n‫عليهــم باملعــروف ثــم توقــف عــن النفقــة عليهــم مــن أول شــوال ‪1431‬هــ‪.‬‬\n‫حيــث كان يدفــع لهــم مبلــغ (‪ )8.000‬ريــال ملصاريــف املعيشــة ويقــوم‬\n‫بتحمــل املصاريــف األخــرى مثــل راتــب الســائق واخلادمــة ومصاريــف‬\n‫املــدارس والدراســة وغيرهــا‪ .‬وقــد ســبق للجنــة اإلصــاح باحملكمــة‬\n‫قبــل ســنتني أن قــدرت النفقــة بســبعة آالف ريــال إال أن هــذا املبلــغ أصبــح‬\n‫ال يكفــي حاجــة األوالد ألنهــم كمــا هــو معلــوم كلمــا كبــر األوالد‬\n‫زادت مصاريفهــم واحتياجاتهــم‪ .‬كمــا أن والدهــم املدعــى عليــه قــد زاد‬\n‫راتبــه مبكرمــة خــادم احلرمــن الشــريفني الــذي أمــر حفظــه اهلل بزيــادة‬\n‫رواتــب املوظفــن وال شــك أن هــذه الزيــادة ملواجهــة النفقــات املتزايــدة‬\n‫ألوالدهــم وأســرهم‪ .‬كمــا أن دخــل املدعــى عليــه قــد زاد مــن جهــة‬\n‫أخــرى‪ ،‬حيــث أنــه أصبــح ميلــك ثــاث عمائــر وعنــد تقديــر النفقــة مــن‬\n\n\n                                                                                    ‫‪148‬‬\n\f      ‫جلنــة اإلصــاح قبــل ســنتني كان ميلــك عمــارة واحــدة‪ .‬هــذا وقــد امتنــع‬\n      ‫املدعــى عليــه عــن تســديد الرســوم الدراســية ألوالده ( ‪...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪)...‬‬\n      ‫عــن العــام الدراســي الســابق وقدرهــا مبلــغ (‪ )79.600‬تســعة وســبعني‬\n      ‫ألــف وســتمائة ريــال وقــد قامــت املدعيــة بتســديد مبلــغ (‪ )39.400‬ريــال‬\n      ‫اقترضتهــا مــن إخواتهــا‪ ،‬ثــم قــام املدعــى عليــه بتســديد القســط الثانــي‪،‬‬\n      ‫أمــا رســوم العــام احلالــي الــذي أوشــك علــى االنتهــاء فلــم يســدد رســومه‬\n                                                                                  ‫للمدرســة‪.‬‬\n      ‫علمـ ًا بــأن أوالدهــا املذكوريــن لــم يســتلموا شــهادات ونتائــج اختبــارات‬\n      ‫الفصــل األول للعــام احلالــي حتــى اآلن بســبب عــدم تســديد الرســوم‪،‬‬\n      ‫ممــا أثــر عليهــم نفســي ًا ومعنوي ـ ًا ممــا قــد يــؤدي إلــى تدهــور مســتواهم‬\n      ‫ـاء علــى مــا تقــدم‪ ،‬ألتمــس مــن فضيلتكم‬     ‫الدراســي‪ .‬ثانيـ ًا ‪ :‬الطلبــات‪ :‬بنـ ً‬\n      ‫إلــزام املدعــى عليــه مبــا يلــي ‪ -1 :‬نفقــة شــهرية جاريــة لــأوالد للمــأكل‬\n      ‫وامللبــس والعــاج حســب مــا يقــدره فضيلتكــم‪ ،‬ألن التقديــر الســابق‬\n      ‫ـداء مــن تاريــخ ‪1431/01/01‬هــ‪.‬‬      ‫أصبــح ال يكفــي حاجاتهــم وذلــك ابتـ ً‬\n      ‫‪ -2‬إلــزام املدعــى عليــه بــأن يدفــع للمدعيــة مبلــغ (‪ )39.400‬ريــال التــي‬\n      ‫دفعتهــا رســوم دراســية حســب ســندات القبــض املرفقــة‪ -3 .‬تســجيل‬\n      ‫االبــن ‪ ...‬باملدرســة ألنــه بلــغ ســن الدراســة‪ -4.‬إلزامــه بتســديد الرســوم‬\n      ‫الدراســية لــأوالد للعــام احلالــي ولألعــوام القادمــة إن شــاء اهلل تعالــى‬\n      ‫بانتظــام‪ -5 .‬مبلــغ (‪ )40.000‬ريــال ســنوي ًا أجــرة مســكن‪ -6 .‬توفيــر‬\n      ‫ســيارة وســائق‪ )) .‬هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫ا‪،‬‬  ‫أجــاب بقولــه بــأن دعــوى املدعيــة غيــر صحيحــة جملــة وتفصي ـ ً‬\n      ‫وأمــا بالنســبة ملصاريــف املــدارس املذكــورة يف الدعــوى فســوف‬\n      ‫أحضــر البينــة يف اجللســة القادمــة ‪ ،‬هكــذا أجــاب ‪ .‬ويف جلســة أخــرى‬\n\n\n‫‪149‬‬\n\f‫يف يــوم الســبت املوافق‪1433/11/20‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10 : 30‬وفيهــا حضــرت املدعيــة أصالــة ‪...‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...‬واملعــرف بهــا مــن قبــل أخيهــا ‪...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر املدعــي وكالــة املــدون تفاصيــل‬\n‫وكالتــه يف اجللســة الســابقة ‪ ،‬وحضــر حلضورهــم املدعــى عليــه أصالــة‬\n‫واملدعــى عليــه وكالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...‬بوكالتــه عــن املدعــى عليــه ‪...‬بالوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة برقــم ‪ 27452‬التــي تخــول لــه املرافعــة واملدافعــة وحضــور‬\n‫اجللســات ‪ ...‬إلــخ ‪ .‬وبعــرض الصلــح بــن الطرفــن وتذكيرهمــا بــأن هــذا‬\n‫الشــقاق وكثــرة احملاكمــات يؤثــر ســلب ًا علــى األوالد ومســتقبلهم وبعــد‬\n‫عــدة محــاوالت امتنــع املدعــى عليــه واملدعيــة بالتســوية ورغبــا يف الصلــح‬\n‫علــى مــا يلــي ‪ -:‬أو ًال ‪ /‬يدفــع املدعــى عليــه نفقــة شــهرية لــكل األوالد‬\n‫قدرهــا ‪ 7.000‬ســبعة االف ريــال وتســتقطع شــهري ًا يف اليــوم األول مــن‬\n‫كل شــهر ميــادي عــن طريــق البنــك مــن حســاب املدعــى عليــه إلــى‬\n‫حســاب املدعيــة ذو األيبــان رقــم ‪ ....‬ثانيـ ًا ‪ /‬يدفــع املدعــى عليــه للمدعيــة‬\n‫مبلغ ـ ًا وقــدره ‪ 56.000‬ســتة وخمســون ألــف ريــال عــن النفقــة املاضيــة‬\n‫لــأوالد وال يكــون للمدعيــة أي مطالبــة غيرهــا يف موضــوع النفقــة‬\n‫املاضيــة لــأوالد ‪ .‬ثالث ـ ًا ‪ /‬يدفــع املدعــى عليــه مبلغ ـ ًا وقــدره ‪39.400‬‬\n‫تســعة وثالثــون ألــف واربعمائــة ريــال للمدعيــة عــن قيمــة األقســاط‬\n‫الدراســية التــي دفعتهــا املدعيــة عــن األوالد وال يكــون للمدعيــة احلــق‬\n‫يف مطالبــة ماليــة يف موضــوع األقســاط الدراســية علــى املدعــى عليــه‬\n‫‪ .‬ويطلــب الطرفــان اثبــات هــذا الصلــح واحلكــم بصحتــه ولزومــه بــن‬\n‫الطرفــن ‪ .‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملــا دار مــن صلــح‬\n\n\n                                                                                       ‫‪150‬‬\n\f      ‫بــن املتخاصمــن بعاليــه ولقــول اهلل تعالــى (( والصلــح خيــر )) ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم (( الصلــح جائــز بــن املســلمني )) وللقاعــدة‬\n      ‫الفقهيــة الكليــة أنــه ال ضــرر وال ضــرار وللقاعــدة الفقهيــة أن الضــرر‬\n      ‫يــزال وملوافقــة الصلــح الــوارد بعاليــه لألصــول الشــرعية والقواعــد‬\n      ‫الفقهيــة فقــد أجــزت الصلــح الــوارد بعاليــه علــى الصفــة املذكــورة‬\n      ‫فيــه وحكمــت بصحتــه ولزومــه بــن الطرفــن ‪ .‬وبــاهلل التوفيــق ‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n      ‫‪ 1433/11/20‬ه ـ الســاعة ‪ 11 : 15‬صباح ـ ًا ‪ .‬ويف هــذا اليــوم الســبت‬\n      ‫املوافــق ‪1434/11/20‬ه ـ وبعــد خــروج املتداعيــن مــن مجلــس احلكــم‬\n      ‫وتوقيــع املدعيــة ووكيلهــا واملعــرف بهــا ومغادرتهــم ‪ ،‬رفــض املدعــى‬\n      ‫عليــه ووكيلــه التوقيــع وقــررا عــدم قناعتهمــا باحلكــم واســتناد ًا الــى‬\n      ‫املــادة ‪ 68‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة جــرى افهــام‬\n      ‫املدعــى عليــه بــأن لــه حــق االعتــراض خــال ثالثــون يوم ـ ًا تبــدأ مــن‬\n      ‫‪1433/11/21‬ه ـ ‪ .‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫الــه وصبحــه وســلم ‪ .‬حــرر يف ‪ 1433/11/20‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة فقــد وردتنــا يف هــذا‬\n      ‫اليــوم االثنــن املوافــق ‪1434/02/04‬ه ـ املعاملــة رقــم ‪34/ 271036‬‬\n      ‫وتاريــخ ‪1434/02/03‬ه ـ مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫والتــي حتــوي قــرار الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال رقــم ‪ 3417309‬يف ‪1434/01/20‬ه ـ‬\n      ‫جتــاه دعــوى ‪...‬ضــد ‪......‬وقــد تضمــن القــرار ( انــه بدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت باألكثريــة املوافقــة علــى‬\n\n\n‫‪151‬‬\n\f‫احلكــم ) قاضيــا االســتئناف ‪...‬ختــم وتوقيــع ‪...‬ختــم وتوقيــع ورئيــس‬\n‫الدائــرة القاضــي ‪...‬ختــم وتوقيــع ولــه وجهــة نظــر وقــد أمــرت بتهميــش‬\n‫ذلــك علــى ضبطــه وســجله وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه‬\n                                           ‫وســلم حــرر يف ‪1434/02/04‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة خلف ـ ًا لفضيلــة‬\n‫القاضــي ‪...‬ويف هــذا اليــوم األحــد املوافــق ‪1434/05/19‬ه ـ كان قــد‬\n‫وردنــا خطــاب صاحــب الفضيلــة رئيــس محكمــة االســتئناف مبكــة‬\n‫املكرمــة املكلــف رقــم ‪ 341015262‬يف ‪1434/05/08‬ه ـ وبرفقهــا‬\n‫صــورة القــرار رقــم ‪ 34202809‬يف ‪1434/04/30‬ه ـ الصــادر مــن‬\n‫الدائــرة الثالثــة لألحــوال الشــخصية املتضمــن انــه بدراســة املعاملــة مــن‬\n‫قضــاة االســتئناف تقــرر مايلــي‪ ، :‬أوال ‪ :‬رفــض االلتمــاس لعــدم انطبــاق‬\n‫التعليمــات عليــه‪ ،‬ثانيـ ًا ‪ :‬بنــاء علــى املــادة ‪ 3/195‬مــن الالئحــة التنفيذيــة‬\n‫لنظــام املرافعــات الشــرعية فيــزود حاكــم القضيــة بصــورة مــن هــذا‬\n‫القــرار إلكمــال الــازم‪ .‬قاضــي اســتئناف ‪...‬ختــم وتوقيــع ‪...‬ختــم وتوقيــع‬\n‫ورئيــس الدائــرة القاضــي ‪...‬ختــم وتوقيــع وموافــق علــى قبــول االلتمــاس‬\n‫وقــد أمــرت بتهميــش ذلــك علــى ضبطــه وســجله وعليــه جــرى التوقيــع‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n                                                  ‫حــرر يف ‪1434/05/19‬ه ـ ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/11/04‬ه ـ واســتناد ًا إلــى الطــاب املقــدم‬\n‫برقــم ‪ 34/2494989‬وتاريــخ ‪1434/11/03‬ه ـ ‪ .‬عليــه حضــر املدعــي‬\n‫وكالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬بوكالتــه‬\n‫عــن ‪...‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــمال جــدة‬\n\n\n                                                                                        ‫‪152‬‬\n\f      ‫ا ‪ :‬لقــد ســبق‬  ‫برقــم ‪ 341322645‬وتاريــخ ‪1434/10/13‬ه ـ ‪ .‬وقــرر قائـ ً‬\n      ‫وحكــم ملوكلتــي ‪...‬علــى املدعــى عليــه بــ((أو ًال ‪ /‬يدفــع املدعــى عليــه‬\n      ‫نفقــة شــهرية لــكل األوالد قدرهــا ‪ 7.000‬ســبعة االف ريــال وتســتقطع‬\n      ‫يومي ـ ًا يف اليــوم األول مــن كل شــهر ميــادي عــن طريــق البنــك مــن‬\n      ‫حســاب املدعــى عليــه حســاب املدعيــة ذو األبيــان رقــم ‪ ....‬ثانيـ ًا ‪ /‬يدفــع‬\n      ‫املدعــى عليــه للمدعيــة مبلغـ ًا وقــدره ‪ 56.000‬ســتة وخمســون ألــف ريــال‬\n      ‫عــن النفقــة املاضيــة لــأوالد وال يكــون للمدعيــة أي مطالبــة غيرهــا‬\n      ‫يف موضــوع النفقــة املاضيــة لــأوالد ‪ .‬ثالث ـ ًا ‪ /‬يدفــع املدعــى عليــه مبلغ ـ ًا‬\n      ‫وقــدره ‪ 39.400‬تســعة وثالثــون ألــف وأربعمائــة ريــال للمدعيــة عــن‬\n      ‫قيمــة األقســاط الدراســية التــي دفعتهــا املدعيــة عــن األوالد وال يكــون‬\n      ‫للمدعيــة احلــق يف مطالبــة ماليــة يف موضــوع األقســاط الدراســية علــى‬\n      ‫املدعــى عليــه )) ‪ ،‬وأقــر أنــي اســتلمت مــايف البنــد الثانــي هــو مبلــغ‬\n      ‫وقــدره ‪ 56.000‬ســتة وخمســون ألــف ريــال عــن النفقــة املاضيــة لــأوالد‪،‬‬\n      ‫واســتلمت البنــد الثالــث هــو مبلــغ وقــدره ‪ 39.400‬تســعة وثالثــون ألــف‬\n      ‫وأربعمائــة ريــال للمدعيــة عــن قيمــة األقســاط الدراســية التــي دفعتهــا‬\n      ‫املدعيــة عــن األوالد ولــم نعــد نطالــب املدعــى عليــه بخصــوص هذيــن‬\n      ‫البنديــن بشــيء‪ .‬هكــذا أقــر ‪ .‬وبذلــك فقــد برئــت ذمــة املدعــى عليــه‬\n      ‫بخصــوص البنــد الثانــي والثالــث ‪ .‬وأمــرت بتهميــش ذلــك علــى ضبطــه‬\n      ‫وصكــه وســجله‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/04‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n\n\n‫‪153‬‬\n\f‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بجــده املســاعد برقــم ‪ 32/9389‬وتاريــخ ‪1434/1/6‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة‬\n‫بجــده برقــم ‪ 33461612‬وتاريــخ ‪1433/11/21‬ه ـ ‪ ،‬املتضمــن دعــوى‬\n‫املــرأة ‪ ...‬ضــد ‪...‬يف نفقــه ‪ ،‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪.‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪،،،،،،‬‬\n\n\n\n\n                                                                              ‫‪154‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":145,"source_page_end":154,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8b69f6d068da7f2c03d47e9d5b972b793cb4ab66392724bb7a135cdb9f9c0d48","normalized_text_hash":"99f839e8e35fa6d70eb58817a2190cee3c6b6569ae9633c347b098581559f8b7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p145-33461612"},{"id":"4d72e010-78d1-5626-9dbf-fff94e73f7bd","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة ابنها املاضية واملستقبلية -أخذ مين األم على ما أنفقته أنه بنية الرجوع على األب -احلكم بالنفقة املاضية واملستقبلية -تقرير النفاذ املعجل بالنفقة املستقبلية.","document_number":"34166698","case_number":"33465156","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"نفقة -مطالبة أم بنفقة ابنها املاضية واملستقبلية -أخذ مين األم على ما أنفقته أنه بنية الرجوع على األب -احلكم بالنفقة املاضية واملستقبلية -تقرير النفاذ املعجل بالنفقة املستقبلية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/21 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34166698 :‬‬\n                          ‫َر ْق ُم الدعوى‪33465156 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34219803‬تاريخه‪1434/5/22 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬مطالبــة أم بنفقــة ابنهــا املاضيــة واملســتقبلية ‪ -‬أخــذ ميــن األم‬\n      ‫علــى مــا أنفقتــه أنــه بنيــة الرجــوع علــى األب ‪ -‬احلكــم بالنفقــة املاضيــة‬\n                     ‫واملســتقبلية ‪ -‬تقريــر النفــاذ املعجــل بالنفقــة املســتقبلية‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــال يف شــرح املنتهــى ‪ ( 242/3‬ولــو امتنــع منهــا أي النفقــة زوج أو‬\n      ‫قريــب فأنفــق عليهــا غيــره رجــع عليــه منفــق علــى زوجــة أو قريــب بنيــة‬\n      ‫رجــوع ألن االمتنــاع قــد يكــون لضعــف مــن وجبــت لــه و قــوة مــن وجبــت‬\n                       ‫عليــه فلــو لــم ميلــك املنفــق الرجــوع لضــاع الضعيــف)‪.‬‬\n                                       ‫‪ .2‬املادة ‪ 199‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا وطلقهــا يف‬\n      ‫‪1433/4/23‬ه ـ ورزقــت منــه مبولــود ذكــر يف حضانتهــا وعمــره‬\n      ‫ســنتان وهــو لــم ينفــق علــى ابنــه مــن تاريــخ طالقهــا إلــى وقــت إقامــة هــذه‬\n      ‫الدعــوى يف ‪1433/10/23‬ه ـ وقــررت أنهــا كانــت تنفــق علــى ابنهــا مــا‬\n      ‫ال يقــل عــن ألــف ريــال ناويــة الرجــوع بهــا علــى املدعــى عليــه وطلبــت‬\n      ‫تقديــر نفقــة شــهرية البنهــا و إلــزام املدعــى عليــه بهــا وإلزامــه أيض ـ ًا‬\n\n‫‪155‬‬\n\f‫أن يســلمها مــا أنفقتــه علــى االبــن للمــدة املاضيــة ‪ -‬قــرر املدعــى عليــه‬\n‫ا وقــرر إنــه ال علــم لــه مبقــدار مــا‬\n                                         ‫مصادقتــه علــى الدعــوى جملــة وتفصيـ ً‬\n‫كانــت املدعيــة تنفقــه علــى االبــن ‪ -‬متــت الكتابــة لقســم اخلبــراء لتقديــر‬\n‫النفقــة املاضيــة واملســتقبلية ومت تقديــر النفقــة مببلــغ قــدره ثمامنائــة ريــال‬\n‫‪ -‬مت أخــذ ميــن املدعيــة علــى أنهــا كانــت تنفــق علــى ابنهــا بنيــة الرجــوع‬\n‫علــى املدعــى عليــه ‪ -‬بنــاء علــى الدعــوى واإلجابــة ولألســباب املرصــودة‬\n‫فقــد صــدر احلكــم علــى املدعــى عليــه أن يســلم للمدعيــة مبلغـ ًا وقــدره‬\n‫ثمانيــة آالف وثمامنائــة ريــال نفقــة ماضيــة ونفقــة شــهرية قدرهــا ثمامنائــة‬\n‫ريــال مســتقبلية مــن تاريــخ ‪1433/3/24‬ه ـ مــع النفــاذ املســتعجل فيمــا‬\n‫يتعلــق بالنفقــة املســتقبلية بكفالــة ورد دعــوى املدعيــة فيمــا زاد علــى‬\n‫هــذا املبلــغ ‪ -‬قنعــت املدعيــة ‪ -‬قــرر املدعــى عليــه عــدم القناعــة ‪ -‬صــدر‬\n          ‫قــرار محكمــة االســتئناف بالريــاض باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم االثنــن املوافــق‪ 1433/10/23‬ه ـ حضــرت حاملــة‬\n‫الســجل املدنــي رقــم واملعــرف بهــا مــن قبــل أخيهــا ‪ .....‬حامــل الســجل‬\n‫املدنــي رقــم‪ ،.....‬وادعــت علــى احلاضــر معهــا ‪ .......‬حامــل الســجل املدنــي‬\n‫برقــم‪ : .......‬قائلــة يف دعواهــا إن املدعــى عليــه كان زوجــي وطلقنــي يف‬\n‫‪1433/4/23‬ه ـ ولــي منــه ابــن يف حضانتــي‪ ،‬اســمه ‪ ...‬وعمــره ســنتان‬\n‫ولــم ينفــق عليــه املدعــى عليــه مــن تاريــخ طالقــي إلــى وقتنــا احلاضــر وقــد‬\n‫أنفقــت عليــه خــال املــدة املاضيــة مــا ال يقــل عــن ألــف ريــال شــهريا ناويــة‬\n‫الرجــوع بهــا علــى والــده املدعــى عليــه وأطلــب تقديــر نفقــة شــهرية البنــي‬\n\n                                                                                         ‫‪156‬‬\n\f      ‫املذكــور وإلــزام املدعــى عليــه بهــا‪ ،‬وإلزامــه بــأن يســلمني مــا أنفقتــه‬\n      ‫علــى ابنــه للمــدة املاضيــة‪ ،‬وباســتجواب املدعــى عليــه قــال‪ :‬مــا ذكرتــه‬\n      ‫املدعيــة مــن أننــي كنــت زوجهــا وطلقتهــا يف ‪1433/4/23‬ه ـ وأن لــي‬\n      ‫منهــا ابــن واســمه وعمــره ســنتان وأنــه يف حضانتهــا وأننــي لــم أنفــق‬\n      ‫عليــه مــن تاريــخ الطــاق إلــى وقتنــا احلاضــر فصحيــح‪ ،‬ومــا ذكرتــه‬\n      ‫مــن مقــدار مــا أنفقتــه علــى ابنــي فــا علــم لــي بــه‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫فقــررت الكتابــة لقســم اخلبــراء لتقديــر النفقــة املاضيــة واملســتقبلية‬\n      ‫البــن الطرفــن ‪ .‬ويف يــوم اإلثنــن املوافــق‪ 1434/03/16‬ه ـ حضــرت‬\n      ‫املدعيــة واملعــرف بهــا مــن قبــل أخيهــا كمــا حضــر املدعــى عليــه وقــد‬\n      ‫وردنــي قــرار قســم الصلــح رقــم ‪..........‬يف ‪1434/02/19‬ه ـ وقــد جــاء‬\n      ‫فيــه مــا نصــه ‪ ( :‬مت االجتمــاع بالطرفــن ومحاولــة الصلــح بينهمــا ولكــن‬\n      ‫لــم يتــم ذلــك حيــث طلبــت املدعيــة أن تكــون النفقــة الشــهرية املاضيــة‬\n      ‫مبلــغ ألــف ومائتــي ريــال حيــث ذكــرت بأنهــا كانــت تذهــب بــه إلــى‬\n      ‫املستشــفيات األهليــة حيــث إنــه يعانــي مــن مــرض الربــو لعــدم وجــود‬\n      ‫إثبــات شــهادة ميــاد للطفــل وتطلــب تقديــر النفقــة املســتقبلية أمــا والــد‬\n      ‫الطفــل فذكــر بأنــه لديــه قســط شــهري قــدره ألفــن وثمامنائــة ريــال وأنه‬\n      ‫ســيتزوج قريبــا وال يســتطيع دفــع أكثــر مــن مبلــغ أربعمائــة ريــال وحيــث‬\n      ‫أن املدعــى عليــه يتقاضــى مرتــب قــدره تســعة آالف وثمانــون ريــاال وبــدل‬\n      ‫نقــل ســبعمائة ريــال حســب شــهادة التعريــف بالراتــب الصــادرة مــن إدارة‬\n      ‫التربيــة والتعليــم بالريــاض فإننــا نــرى أن تكــون النفقــة الشــهرية للطفــل‬\n      ‫مبلــغ ثمامنائــة ريــال وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم أعضــاء مكتــب الصلــح توقيعــه توقيعــه) فجــرى‬\n      ‫عــرض اليمــن علــى املدعيــة بأنهــا أنفقــت علــى ابنهــا مــا ال يقــل عــن‬\n\n\n‫‪157‬‬\n\f‫ثمامنائــة ريــال شــهريا ناويــة الرجــوع بهــا علــى املدعــى عليــه فاســتعدت‬\n‫ببذلهــا ثــم حلفــت قائلــة ‪ ( :‬واهلل الــذي ال إلــه إال هــو إننــي قــد أنفقــت‬\n‫علــى ابنــي مــا ال يقــل عــن ثمامنائــة ريــال شــهريا ناويــة الرجــوع بهــا علــى‬\n‫املدعــى عليــه ابتــداء مــن ‪1433/04/23‬هــ) هكــذا حلفــت فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا جــاء يف قــرار مكتــب الصلــح‬\n‫وبنــاء علــى مــا قــرره أهــل العلــم قــال يف شــرح املنتهــى ‪( : 242/3‬ولــو‬\n‫امتنــع منهــا ‪ -‬أي النفقــة ‪ -‬زوج أو قريــب فأنفــق عليهمــا غيــره رجــع‬\n‫عليــه منفــق علــى زوجــة وقريــب بنيــة رجــوع ألن االمتنــاع قــد يكــون‬\n‫لضعــف مــن وجبــت لــه وقــوة مــن وجبــت عليــه فلــو لــم ميلــك املنفــق الرجــوع‬\n‫لضــاع الضعيــف) وبنــاء علــى املــادة التاســعة والتســعني بعــد املائــة مــن‬\n‫نظــام املرافعــات الشــرعية لــذا فقــد حكمــت علــى املدعــى عليــه بــأن‬\n‫يســلم للمدعيــة مبلغــا قــدره ثمانيــة آالف وثمامنائــة ريــال عــن نفقــة ابنــه‬\n‫مــن ‪1433/04/23‬ه ـ إلــى ‪1434/03/22‬ه ـ وأن يســلم للمدعيــة نفقــة‬\n‫شــهرية البنــه قدرهــا ثمامنائــة ريــال ابتــداء مــن ‪1434/03/24‬ه ـ مــع‬\n‫النفــاذ املعجــل فيمــا يتعلــق بالنفقــة املســتقبلية بكفالــة ورددت دعــوى‬\n‫املدعيــة يف املطالبــة مبــا زاد عــن مــا حكــم بــه وأخليــت ســبيل املدعــى‬\n‫عليــه منــه وبعــرض احلكــم علــى الطرفــن قنعت بــه املدعية وأمــا املدعى‬\n‫عليــه فلــم يقنــع بــه وطلــب االســتئناف فأجبتــه لطلبــه وأفهمتــه بــأن عليــه‬\n‫املراجعــة يــوم األحــد املوافــق ‪1434/03/22‬ه ـ ال ســتالم صــورة من صك‬\n‫احلكــم لتقــدمي معارضتــه عليــه خــال مــدة ال تتجــاوز ثالثــن يومــا فــإن‬\n‫لــم يقــدم معارضتــه خاللهــا ســقط حقــه يف تقــدمي الالئحــة االعتراضيــة‬\n‫واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/16‬ه ـ‬\n\n\n                                                                                         ‫‪158‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/06/12‬ه ـ‬\n      ‫وردتنــا املعاملــة مــن محكمــة االســتئناف بالريــاض وقــد همــش علــى‬\n      ‫ظهــر الصــك مبــا نصــه ( تظهيــرات الدائــرة الثانيــة لألحــوال الشــخصية‬\n      ‫واإلنهــاءات مبحكمــة االســتئناف مبنطقــة الريــاض ‪ ،‬احلمــد هلل‬\n      ‫وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34166698‬وتاريــخ‬\n      ‫‪1434/03/21‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ )....( /‬وأصدرنــا القــرار‬\n      ‫رقــم ‪ 34219803‬وتاريــخ ‪1434/05/22‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم ‪ ،‬واهلل املوفــق ‪ .‬عضــو ختمــه وتوقيعــه عضــو ختمــه وتوقيعــه‬\n      ‫رئيــس الدائــرة ختمــه وتوقيعــه ‪ ) .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/06/12‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331323312‬وتاريــخ ‪1434/5/8‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪)....( /‬‬\n      ‫املســجل برقــم ‪ 34166698‬وتاريــخ ‪1434/3/21‬ه ـ اخلــاص بدعــوى(‪)....‬‬\n      ‫ضــد (‪ )....‬يف قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪،‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪159‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":155,"source_page_end":159,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6442f9a8ce8a05992fbaca1728f751d565475fcf2730f774e9888511788f0ee1","normalized_text_hash":"8c5c45ebba4608c2bea2bed1b19f3b902c05a0ac085daacccb90cfb71990c22d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p155-34166698"},{"id":"906cd038-faeb-5ed5-ae9b-a32385f96a11","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة الزوجة املاضية ونفقة األوالد املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء -حلف مين على عدم اإلنفاق -احلكم بنفقة ماضية ومستقبلية -الغائب على حجته.","document_number":"33467099","case_number":"33184519","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/28","year":"1434","subject":"نفقة -نفقة الزوجة املاضية ونفقة األوالد املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء -حلف مين على عدم اإلنفاق -احلكم بنفقة ماضية ومستقبلية -الغائب على حجته.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/28 :‬هـ‬\n                  ‫ُ‬                 ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪33467099 :‬‬\n                     ‫َر ْق ُم الدعوى‪33184519 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3436709‬تاريخه‪1434/2/13 :‬هـ‬\n\n\n\n  ‫نفقــة ‪ -‬نفقــة الزوجــة املاضيــة ونفقــة األوالد املاضيــة واملســتقبلية‬\n  ‫‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪ -‬حلــف ميــن علــى عــدم‬\n  ‫اإلنفــاق ‪ -‬احلكــم بنفقــة ماضيــة ومســتقبلية ‪ -‬الغائــب علــى حجتــه‪.‬‬\n\n\n\n\n         ‫‪ -1‬قوله تعالى ‪ ( :‬وعلى املولود له رزقهن وكسوتهن باملعروف )‬\n  ‫‪ -2‬جــاء يف كتــاب العــده شــرح العمــده ‪ « 36/2‬واألصــل يف وجــوب‬\n  ‫النفقــة قولــه تعالــى « لينفــق ذو ســعة مــن ســعته ومــن قــدر عليــه رزقــه‬\n                                                        ‫فلينفــق ممــا اتــاه اهلل»‬\n  ‫‪ -3‬وفــى حديــث جابــر أن النبــي صلــى اهلل عليــه وســلم خطــب فقــال‬\n  ‫«اتقــوا اهلل يف النســاء فإنهــن عــوان عندكــم ‪ -‬اخذمتوهــن بأمــان اهلل‬\n  ‫واســتحللتم فروجهــن بكلمــة اهلل ولهــن عليكــم رزقهــن وكســوتهن‬\n  ‫باملعــروف» رواه مســلم والترمــذي وفيــه «وحقهــن عليكــم أن حتســنوا‬\n                   ‫إليهــن يف كســوتهن وطعامهــن» وقــال حديــث صحيــح‬\n     ‫‪ -4‬وقــال عليــه الصــاة و الســام لهنــد «خــذي مــا يكفيــك وولـ ِ‬\n  ‫ـدك»‬\n  ‫باملعــروف حــن قالــت إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي مــن‬\n                                  ‫النفقــة مــا يكفينــي وولــدي ‪ .‬متفــق عليــه‬\n                    ‫‪ -5‬أجمع الفقهاء على وجوب نفقة الزوجات إال الناشز‬\n                                                     ‫‪ -6‬قاعدة ‪ :‬األصل العدم‬\n\n                                                                                      ‫‪160‬‬\n\f                                 ‫‪ -7‬قاعدة من أدى عن غيره حق ًا واجب ًا رجع به‬\n                                    ‫‪ -8‬املادة (‪ )55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم الــذي‬\n      ‫تبلــغ لغيــر شــخصه أكثــر مــن مــرة ولــم يحضــر‪ ،‬أن املدعــى عليــه‬\n      ‫زوجهــا ورزقــت منــه بثالثــة أوالد وإنهــا الزالــت يف عصمتــه وهــى عنــد‬\n      ‫أهلهــا ولــم يرجعهــا بعــد حصــول خــاف ومكثــت مــدة قدرهــا ســنتان‬\n      ‫بــدون نفقــة لهــا وألوالدهــا وقــد تولــى أخ املدعــى عليــه نفقــة األوالد‬\n      ‫وطالبــت املدعيــة نفقتهــا املاضيــة ونفقــة أوالدهــا املســتقبلية ‪ -‬أبــرزت‬\n      ‫املدعيــة كــرت العائلــة وشــهادة ميــاد أحــد األبنــاء ‪ -‬مت تكليــف قســم‬\n      ‫اخلبــراء باحملكمــة لتقديــر نفقــة املدعيــة املاضيــة وأوالدهــا وقــدرت‬\n      ‫نفقــة املدعيــة املاضيــة شــهريا ســبعمائة ريــال واألبنــاء الثالثــة ألــف‬\n      ‫وخمســمائة ريــال لــكل واحــد خمســمائة ريــال ‪ -‬قــرر ناظــر القضيــة‬\n      ‫لألســباب التــي ذكرهــا ولقولــه تعالــى ((لينفــق ذو ســعه مــن ســعته))‬\n      ‫احلكــم علــى املدعــى عليــه بتســليم املدعيــة نفقتهــا املاضيــة مبلغــا قــدره‬\n      ‫ســبعة عشــر ألفــا ومائــة وســته وعشــرون ريــاال ونفقــة مســتقبلية لــأوالد‬\n      ‫ألــف وخمســمائة ريــال لــكل ولــد خمســمائة ريــال والغائــب علــى حجتــه‬\n      ‫إذا حضــر ‪ -‬مت بعــث نســخة مــن احلكــم إلــى املدعــى عليــه حســب‬\n                               ‫املتبــع‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪161‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده‪ ،‬وبعــد فلــدي‬\n‫أنــا‪ .....‬القاضــي يف احملكمــة العامــة مبكة املكرمة وبناء على املعاملة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة‬\n‫برقــم ‪ 33184519‬وتاريــخ ‪ 1433/03/14‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 33175346‬وتاريخ ‪ 1433/01/25‬هـ ففي يوم السبت ‪1433/4/24‬هـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة والنصــف صباحـ ًا للنظــر يف دعــوى ضد‬\n‫وفيهــا حضــرت املدعيــة ‪ .....‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬املعــرف بهــا مــن قبــل والدهــا‪ .....‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة‬\n‫شــرعية وقــد وردنــا مــن قســم احملضريــن باحملكمــة إفــادة احملضــر أنــه‬\n‫مت الوصــول إلــى العنــوان املشــار إليــه‪ ،‬وبطــرق بــاب املدعــى عليــه عــدة‬\n‫مــرات ويف أوقــات مختلفــة لــم يــرد علينــا أحــد‪ ،‬وباالتصــال علــى رقــم‬\n‫جــوال أخيــه كذلــك لــم يــرد علينــا أحــد أه ـ ورفعــت اجللســة إلبالغــه‬\n‫باحلضــور ثــم إنــه يف يــوم األربعــاء ‪1433/6/18‬ه ـ الســاعة احلاديــة‬\n‫عشــرة صباحــا افتتحــت اجللســة وفيهــا حضــرت املدعيــة املعــرف بهــا‬\n‫مــن قبــل والدهــا ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n‫ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية ولــم يردنــا مــا‬\n‫يفيــد تبلغــه ورفعــت اجللســة إلبالغــه باحلضــور ثــم إنــه يف يــوم األربعــاء‬\n‫‪1433/7/2‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف صباح ـ ًا‬\n‫وفيهــا حضــرت املدعيــة املعــرف بهــا مــن قبــل والدهــا ‪ .....‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال‬\n\n                                                                                      ‫‪162‬‬\n\f      ‫مــن ميثلــه بوكالــة شــرعية وقــد وردنــا مــن قســم احملضريــن يف احملكمة‬\n      ‫إفــادة احملضــر املتضمنــة مــا نصــه‪« :‬ذهبــت إلــى العنــوان املشــار إليــه‬\n      ‫أعــاه وبطــرق بــاب املدعــى عليــه عــدة مــرات ويف أوقــات مختلفــة لــم يــرد‬\n      ‫علينــا أحــد وباالتصــال علــى رقــم جــوال املدعــى عليــه كذلــك لــم يــرد‬\n      ‫علينــا أحــد وباالتصــال علــى جــوال أخيــه رد ولكنــه اعتــذر عــن تبليــغ‬\n      ‫أخيــه بحجــة أنــه ال يــراه منــذ فتــرة» أ ـ ه ـ كمــا هــو مــدون يف أصــل ورقــة‬\n      ‫التبليــغ املقيــدة يف احملكمــة برقــم ‪ 331160587‬يف ‪1433/6/21‬ه ـ‬\n      ‫واملرفقــة يف املعاملــة كمــا وردنــا كتــاب مديــر قســم أمــن احملاكــم‬\n      ‫برقــم ‪ 505‬يف ‪1433/6/30‬ه ـ وبرفقــه إفــادة مديــر مركــز شــرطة‬\n      ‫التنعيــم برقــم ‪ 145157‬يف ‪1433/6/15‬ه ـ املتضمنــة‪« :‬أنــه مــن خــال‬\n      ‫البحــث والتحــري عــن املذكــور واالنتقــال عــدة مــرات لــم يعثــر عليــه‬\n      ‫ومت االتصــال بــه عــدة مــرات وإبالغــه باملراجعــة إال أنــه لــم يراجــع ممــا‬\n      ‫يــدل علــى تهربــه كمــا يتضــح لكــم مــن التقريــر املرفــق» ومرفــق أصلــه‬\n      ‫يف املعاملــة وحيــث األمــر مــا ذكــر لــذا فقــد قــررت النظــر يف القضيــة‬\n      ‫ضــده غيابي ـ ًا حســب املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحــه التنفيذيــة وبســؤال املدعيــة عــن دعواهــا ادعــت قائلة‪:‬‬\n      ‫إن املدعــى عليــه املدعــو ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫زوجــي تزوجنــي بالعقــد الصحيــح بواليــة والــدي بتاريــخ ‪1422/8/16‬ه ـ‬\n      ‫علــى مهــر قــدره عشــرون ألــف ريــال اســتلمتها كاملــة ودخل بــي الدخول‬\n      ‫الشــرعي وقــد أجنبــت منــه علــى فــراش الزوجيــة ثالثــة أوالد وهــم كل‬\n      ‫مــن املولــودة بتاريــخ ‪1423/12/12‬ه ـ و املولــودة بتاريــخ ‪1425/6/12‬ه ـ‬\n      ‫واملولــود بتاريــخ ‪1428/2/10‬ه ـ والزلــت يف عصمتــه وتقدمــت بدعــوى‬\n      ‫أطالــب بفســخ نكاحــي منــه وأوالدي منــه املذكوريــن يقيمــون حتــت‬\n\n\n‫‪163‬‬\n\f‫حضانتــي وقــد حصــل خــاف بســيط بينــي وبينــه وطلبــت منــه الذهــاب‬\n‫بــي إلــى بيــت أهلــي فذهــب بــي وذلــك يف ‪1431/6/18‬ه ـ ولــم يرجعنــي‬\n‫ولــم يســأل عنــي طيلــة تلــك املــدة والزلــت عنــد أهلــي وإن أخــاه جــزاه‬\n‫اهلل خيــر ًا يصــرف علــى أوالدي يف بدايــة األمــر ألــف ريــال شــهري ًا ثــم‬\n‫زادهــا حتــى كانــت ألــف وخمســمائة ريــال باإلضافــة إلــى كســوة‬\n‫العيــد أطلــب إلــزام املدعــى عليــه بدفــع نفقــة لــي مــدة بقائــي عنــد أهلــي‬\n‫مــن تاريــخ ‪1431/6/18‬ه ـ وحتــى هــذا اليــوم ‪1433/7/2‬ه ـ ودفــع نفقــة‬\n‫شــهرية مســتقبلية ألوالدي املذكوريــن ألتولــى النفقــة عليهــم منهــا هــذه‬\n‫دعــواي وبطلــب البينــة مــن املدعيــة علــى صحــة دعواهــا قالــت بينتــي‬\n              ‫علــى ذلــك أصــل كــرت العائلــة اخلــاص بزوجــي وقــد أبرزتــه‬\n‫وباالطالع عليه وجدته يتضمن أن اسمه ورقم سجله املدني وأن املدعية‬\n‫مضافــة معــه كزوجــة وأوالده مــن مواليــد ‪1423/12/12‬ه ـ مــن مواليــد‬\n‫‪1425/6/12‬ه ـ ومرفــق صــورة منــه يف املعاملــة كمــا أبــرزت شــهادة‬\n‫ميــاد خاصــة بابنهــا وفيــه أن ميــاده بتاريــخ ‪1428/2/10‬ه ـ ومرفــق‬\n‫صــورة منــه يف املعاملــة وقالــت إنــه لــم يقــم بإضافتــه يف كــرت العائلــة‬\n‫هكــذا قــررت فجــرى ســؤالها عــن عقــد النــكاح؟ فقالت إنــه ليس لدي‬\n‫بــل هــو لــدى املدعــى عليــه وليــس لــدي حتــى صــورة منــه هكــذا قــررت‬\n‫فجــرى ســؤالها هــل لديــك بينــة علــى أن املدعــى عليــه لــم ينفــق عليــك مــن‬\n‫تاريــخ ‪1431/6/18‬ه ـ وحتــى تاريــخ ‪1433/7/2‬هــ؟ فقالــت ليــس لــدي‬\n‫بينــة علــى ذلــك هكــذا قــررت عنــد ذلــك قــررت الكتابــة لهيئــة النظــر‬\n‫يف احملكمــة مــن أجــل االجتمــاع باملدعيــة مبعــرف بهــا لدراســة حالهــا‬\n‫واإلفــادة عــن مقــدار نفقتهــا املثليــة خــال املــدة مــن ‪1431/6/18‬ه ـ‬\n‫وحتــى ‪1433/7/2‬ه ـ وحتديــد نفقــة شــهرية مســتقبلية ألوالدهــا ورفعــت‬\n\n\n                                                                                       ‫‪164‬‬\n\f      ‫اجللســة لذلــك ثــم إنــه يف يــوم االثنــن ‪1433/8/5‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الثانيــة عشــرة ظهــر ًا وفيهــا حضــرت املدعيــة برفقــة والدهــا‬\n      ‫املعــرف بهــا ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية‬\n      ‫وقــد وردنــا مــن قســم احملضريــن يف احملكمــة إفــادة احملضــر املتضمنــة‪:‬‬\n      ‫«أنــه مت تســليم صــورة مــن الطلــب الخيــه واســتعد بإبــاغ اخيــه باملوعــد»‬\n      ‫أ ـ ه ـ كمــا هــو مــدون يف أصــل ورقــة التبليــغ املقيــدة برقــم ‪331252284‬‬\n      ‫يف ‪1433/7/5‬ه ـ املرفقــة يف املعاملــة كمــا جــرى االتصــال عليــه مــن‬\n      ‫املكتــب القضائــي علــى جوالــه املوضــح يف ورقــة التبليــغ برقــم إال أنــه‬\n      ‫لــم يتــم الــرد وكان قــد جــرى بعــث املعاملــة لهيئــة النظــر يف احملكمــة‬\n      ‫مــن أجــل تقديــر النفقــة إال أنهــا لــم تــرد حتــى اآلن وحلــن ورودهــا فقــد‬\n      ‫رفعــت اجللســة ثــم إنــه يف يــوم الثالثــاء ‪1433/8/27‬ه ـ الســاعة احلاديــة‬\n      ‫عشــرة صباحـ ًا افتتحــت اجللســة وفيهــا حضــرت املدعيــة برفقــة والدهــا‬\n      ‫املعــرف بهــا ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة شــرعية‬\n      ‫وكان قــد جــرت الكتابــة منــي لهيئــة النظــر يف احملكمــة باخلطــاب‬\n      ‫رقــم ‪ 33175346‬يف ‪1433/7/15‬ه ـ مــن أجــل االجتمــاع بــن الطرفــن‬\n      ‫املتنازعــن ومحاولــة حــل اإلشــكال القائــم بينهمــا وإال إفادتنا مبا يرونه‬\n      ‫حــول حتديــد مقــدار النفقــة املثليــة للزوجــة مــن تاريــخ ‪1431/6/18‬ه ـ‬\n      ‫وحتــى ‪1433/7/2‬ه ـ وحتديــد نفقــة شــهرية مســتقبلية ألوالدهــا أ ‪ ،‬ه ـ‬\n      ‫فوردنــا اجلــواب مــن هيئــة النظــر برقــم ‪ 3175346‬يف ‪1433/7/27‬ه ـ‬\n      ‫مفــاده أنــه مت حتديــد ثــاث مواعيــد بهيئــة النظــر وحيــث إنهــا حضــرت‬\n      ‫فيهــا املدعيــة ولــم يحضــر فيهــا املدعــى عليــه لــذا تعــذر إكمــال الالزم أ‬\n      ‫‪ ،‬ه ـ وحيــث األمــر مــا ذكــر فقــد قــررت إعادتهــا مــرة ثانيــة لهيئــة النظر‬\n      ‫إلكمــال الــازم علــى ضــوء خطابنــا الســابق ولــو لــم يحضــر املدعــى‬\n\n\n‫‪165‬‬\n\f‫عليــه وحلــن ورود اجلــواب فقــد رفعــت اجللســة ثــم إنــه يف يــوم الســبت‬\n‫‪1433/11/27‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة ظهــر ًا وفيهــا‬\n‫حضــرت املدعيــة برفقــة والدهــا املعــرف بهــا ولــم يحضــر املدعــى عليــه‬\n‫وال مــن ميثلــه بوكالــة شــرعية وقــد وردنــا مــن هيئــة النظــر يف احملكمــة‬\n‫باخلطــاب رقــم ‪ 33175346‬يف ‪1433/11/27‬ه ـ قرارهــم املــؤرخ يف‬\n‫‪1433/11/27‬ه ـ املتضمــن بعــد املقدمــة مــا نصــه ‪ « :‬عليــه فــإن النفقــة‬\n‫املثليــة للزوجــة عــن الفتــرة مــن ‪1431/6/18‬ه ـ وحتــى ‪1433/7/2‬ه ـ أي‬\n‫أربعــة وعشــرون شــهرا وأربعــة عشــر يومــا هــي ســبعمائة ريــال شــهريا أي‬\n‫مــا مجموعــه ســبعة عشــر ألفــا ومائــة وســتة وعشــرين ريــاال‪ ،‬أمــا نفقــة‬\n‫األبنــاء فهــي لــكل ابــن خمســمائة ريــال حيــث إن أبنــاء املدعيــة بنتــان‬\n‫وابــن واحــد وذلــك شــهريا هــذا مــا جــرى تقريــره « عضــوا هيئــة النظــر يف‬\n‫احملكمــة توقيعــه توقيعــه وبعــرض القــرار علــى املدعيــة قــررت املوافقــة‬\n‫عليــه وبطلــب اليمــن مــن املدعيــة علــى صحــة دعواهــا اســتعدت بذلــك‬\n‫ثــم حلفــت قائلــة ‪ « :‬واهلل العظيــم الــذي ال إلــه إال هــو إن املدعــى عليــه‬\n‫زوجــي وقــد أجنبــت منــه علــى فــراش الزوجيــة ثالثــة أوالد وهــم كل مــن‬\n‫ووأوالدي منــه املذكوريــن يقيمــون حتــت حضانتــي وقــد حصــل خــاف‬\n‫بســيط بينــي وبينــه وطلبــت منــه الذهــاب بــي إلــى بيــت أهلــي فذهــب‬\n‫بــي وذلــك يف ‪1431/6/18‬ه ـ ولــم يرجعنــي حتــى اآلن ولــم يســأل عنــي‬\n‫طيلــة تلــك املــدة والزلــت عنــد أهلــي وإن أخــاه يصــرف علــى أوالدي يف‬\n‫بدايــة األمــر ألــف ريــال شــهري ًا ثــم زادهــا حتــى كانــت ألــف وخمســمائة‬\n‫ريــال باإلضافــة إلــى كســوة العيــد واهلل العظيــم واهلل العظيــم « هكــذا‬\n‫حلفــت فجــرى ســؤال املدعيــة هــل لديــك مــا تريديــن إضافتــه ؟ فقالــت ‪:‬‬\n‫ليــس لــدي ســوى مــا قدمــت وأطلــب الفصــل يف القضيــة هكــذا قــررت‬\n\n\n                                                                                     ‫‪166‬‬\n\f      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى وبعــد دراســة القضيــة وتأملهــا ومبــا‬\n      ‫أن املدعيــة تطالــب املدعــى عليــه الغائــب عــن املجلــس الشــرعي لكونــه‬\n      ‫زوجهــا بنفقتهــا مــن تاريخ ‪1431/6/18‬ه ـ وحتى ‪1433/7/2‬هـ وحتديد‬\n      ‫نفقــة شــهرية مســتقبلية ألوالدهــا منــه ونظــرا لتبلــغ املدعــى عليــه لغيــر‬\n      ‫شــخصه أكثــر مــن مــرة إال أنــه لــم يحضــر أو يــوكل مــن ينــوب عنــه‬\n      ‫باحلضــور وعــدم حضــوره مــع تبلغــه يعــد نكــوال عــن اجلــواب والنــاكل‬\n      ‫يقضــى عليــه بالنكــول كمــا قــرر ذلــك أهــل العلــم يف مظانــه ومبــا‬\n      ‫أن نفقــة الزوجــة واألوالد واجبــة علــى الــزوج قــال تعالــى ‪ « :‬لينفــق ذو‬\n      ‫ســعة مــن ســعته « والظاهــر مــن حــال الــزوج عــدم النفقــة علــى زوجتــه‬\n      ‫وعلــى أوالده لكونــه لــم يســأل عنهــم مــن فتــرة طويلــة وعــدم جتاوبــه‬\n      ‫مــع تبليغــات احملكمــة وتــرك زوجتــه مــن فتــرة عنــد أهلهــا مــن غيــر‬\n      ‫ســؤال وألن األصــل العــدم فاألصــل عــدم إنفــاق املدعــى عليــه علــى‬\n      ‫املدعيــة وأوالدهــا وألن الظاهــر أن مــن كان لديــه طفــل فإنــه ينفــق‬\n      ‫عليــه الســيما األم وألن الظاهــر أن املــرء إمنــا ينفــق مــن مالــه وألن مــن‬\n      ‫أدى عــن غيــره حقـ ًا واجبــا رجــع بــه جــاء يف كتــاب العــدة شــرح العمــدة‬\n      ‫‪ « : 36/2‬واألصــل يف وجــوب النفقــة قولــه ســبحانه ‪ ( :‬ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة‬\n      ‫الل )‪ ،‬ويف حديــث‬               ‫ـاه َّ ُ‬        ‫مِ ــنْ َسـ َـع ِت ِه َو َمــنْ قُ ــدِ َر َع َل ْي ـ ِه ِر ْزقُ ـ ُه َف ْل ُي ْنفِ ـ ْـق ِ َّ‬\n                                           ‫مــا آ َتـ ُ‬\n      ‫جابــر أن النبــي صلــى اهلل عليــه وســلم خطــب فقــال ‪ ( :‬اتقــوا اهلل يف‬\n      ‫النســاء فإنهــن عــوان عندكــم‪ ،‬أخذمتوهــن بأمانــة اهلل واســتحللتم‬\n      ‫فروجهــن بكلمــة اهلل ولهــن عليكــم رزقهــن وكســوتهن باملعــروف)‪.‬‬\n      ‫رواه مســلم ورواه الترمــذي ‪ ،‬وفيــه‪ ( :‬وحقهــن عليكــم أن حتســنوا‬\n      ‫إليهــن يف كســوتهن وطعامهــن )‪ .‬وقــال‪ :‬حديــث صحيــح‪ .‬و قــال عليــه‬\n      ‫الســام لهنــد ‪ ( :‬خــذي مــا يكفيــك وولــدك باملعــروف ) حــن قالــت لــه‬\n\n\n‫‪167‬‬\n\f‫‪ :‬إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي مــن النفقــة مــا يكفينــي‬\n‫وولــدي‪ .‬متفــق عليــه‪ .‬وأجمعــوا علــى وجــوب نفقــة الزوجــات إال الناشــز‬\n‫ذكــره ابــن املنــذر‪ ،‬وقــال اهلل ســبحانه‪َ ( :‬و َع َلــى ْال َْو ُلــو ِد َل ـ ُه ِر ْزقُ ُهـ َّـن‬\n‫وف )‪ ،‬واملعــروف قــدر الكفايــة وقــدر الكفايــة‬                            ‫ك ْسـ َـو ُت ُه َّن ِب ْال َْعـ ُـر ِ‬\n                                                                                                                 ‫َو ِ‬\n‫غيــر مقــدر فيرجــع فيــه إلــى اجتهــاد احلاكــم عنــد التنــازع» أ‪.‬ه ـ ونظــرا‬\n‫لتقديــر النفقــة ســواء للزوجــة أو لــأوالد مــن قبــل أهــل اخلبــرة وقــد حلفت‬\n‫املدعيــة اليمــن الشــرعية بعــد طلبهــا منهــا علــى صحــة دعواهــا وبنــاء‬\n‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة لذلــك كلــه فقــد ألزمــت املدعــى عليــه الغائــب عــن املجلــس‬\n‫الشــرعي مبــا يلــي ‪ :‬أوال ‪ :‬يدفــع مبلغــا وقــدره ســبعة عشــر ألفــا ومائــة‬\n‫وســتة وعشــرون ريــاال للمدعيــة عــن نفقتهــا للمــدة مــن ‪1431/6/18‬ه ـ‬\n‫وحتــى ‪1433/7/2‬ه ـ ثانيــا ‪ :‬يدفــع مبلغــا وقــدره ألــف وخمســمائة ريــال‬\n‫شــهريا للمدعيــة نفقــة مســتقبلية لــأوالد الثالثــة ‪...‬و‪ ...‬و‪ ...‬اعتبــارا مــن‬\n‫‪1433/12/1‬ه ـ لــكل واحــد منهــم خمســمائة ريــال ومبــا تقدم حكمت‬\n‫وبعــرض احلكــم علــى املدعيــة قــررت القناعــة بــه ويعــد احلكــم يف حــق‬\n‫احملكــوم عليــه غيابيــا والغائــب علــى حجتــه إذا حضــر وأمــرت ببعــث‬\n‫نســخة مــن صــك احلكــم للمحكــوم عليــه لتقــدمي اعتراضــه عليــه خــال‬\n‫ثالثــن يومـ ًا مــن تاريــخ تبلغــه باحلكــم وإذا لــم يتقــدم بذلــك خــال املــدة‬\n‫املذكــور فسيســقط حقــه بطلــب االســتئناف وسيكتســب احلكــم‬\n‫القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                      ‫وصحبــه وســلم‪ ،‬حــرر يف ‪1433/11/27‬ه ـ‬\n‫تظهيــرات الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبكــة املكرمــة احلمــد‬\n\n\n                                                                                                                        ‫‪168‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":160,"source_page_end":168,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a38c57596c8f7bca47cb5f782cf1a752cea4dded1922730d1f48ddc46ae376dd","normalized_text_hash":"b31b0fbdaebfddc1ac90b178c4351c0c02df2589c3ac9b8dc6dcbcaa7e0022d1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p160-33467099"},{"id":"7b883104-4773-517b-8514-a1e9c1a37c9b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة -املطالبة بالنفقة املاضية -املطالبة بقيمة الذهب -املطالبة بفاتورة الهاتف الثابت -دفع الزوج بنشوز الزوجة- إذا اختلف الزوجان يف النشوز فالقول قول الزوجة مع ميينها .","document_number":"33473430","case_number":"32225389","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/20","year":"1434","subject":"نفقة -نفقة زوجة -املطالبة بالنفقة املاضية -املطالبة بقيمة الذهب -املطالبة بفاتورة الهاتف الثابت -دفع الزوج بنشوز الزوجة- إذا اختلف الزوجان يف النشوز فالقول قول الزوجة مع ميينها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/20 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33473430 :‬‬\n                    ‫َر ْق ُم الدعوى‪32225389 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34269552‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n\n ‫نفقــة ‪ -‬نفقــة زوجــة ‪ -‬املطالبــة بالنفقــة املاضيــة‪ -‬املطالبــة بقيمــة‬\n ‫الذهــب‪ -‬املطالبــة بفاتــورة الهاتــف الثابــت‪ -‬دفــع الــزوج بنشــوز الزوجة‪-‬‬\n   ‫إذا اختلــف الزوجــان يف النشــوز فالقــول قــول الزوجــة مــع ميينهــا ‪.‬‬\n\n\n\n\n ‫مــا قــرره الفقهــاء (مــن أن الزوجــن إذا اختلفــا يف النشــوز فالقــول قولهــا‬\n                                        ‫مــع مينيهــا) الشــرح الكبيــر( ‪)262/6‬‬\n\n\n\n\n ‫ادعــى املدعــي وكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه ولــم‬\n ‫تنجــب منــه وقــام بإحضارهــا يف ‪1431/1/1‬ه ـ وتركهــا عنــد أهلهــا‬\n ‫حتــى صــدور احلكــم بفســخ نكاحهــا يف ‪1433/2/2‬ه ـ ‪ -‬طلــب املدعــى‬\n ‫وكالــة نفقــة موكلتــه ملــدة ســنة وأربعــة أشــهر وقيمــة الذهــب الــذي‬\n ‫أخــذه منهــا وأقــر بــه املدعــى عليــه يف احلكــم وقيمــة فاتــورة الهاتــف‬\n ‫الثابــت وقدرهــا ثمامنائــة ريــال‪ -‬أجــاب املدعــى عليــه بصحــة الدعــوى‬\n ‫ودفــع بــأن ســبب عــدم النفقــة هــو نشــوز املدعيــة وأمــا الذهــب فهــو عطيــة‬\n ‫مــن املدعيــة كمــا يحصــل بــن األزواج وأمــا فاتــورة الهاتــف فــا عالقــة‬\n ‫لــه بهــا واملدعيــة هــي التــي تســتعمله وهــي التــي قامــت بتركيبــه باســمها‬\n ‫يف املنــزل وطلــب املدعــى عليــه رد الدعــوى ‪ -‬قــرر املدعــي وكالــة أن‬\n\n                                                                                       ‫‪170‬‬\n\f      ‫الصحيــح مــا جــاء يف دعــواه و أبــرز صــك احلكــم املتضمــن ‪ :‬احلكــم‬\n      ‫بفســخ نــكاح املدعيــة مــن املدعــى عليــه علــى عــوض و قــد جــاء فيــه‬\n      ‫إقــرار املدعــى عليــه بأخــذه مــن الذهــب مــا قيمتــه عشــرة آالف ريــال‪-‬‬\n      ‫بنــاء علــى مــا قــرره الفقهــاء مــن أن الزوجــن إذا ختلفا يف النشــوز فالقول‬\n      ‫قــول الزوجــة مــع ميينهــا انظــر الشــرح الكبيــر (‪ - )262/6‬قــرر املدعــى‬\n      ‫عليــه أنــه يطلــب ميــن املدعيــة علــى فاتــورة الهاتــف وعلــى نفــي النشــوز‪-‬‬\n      ‫حضــرت املدعيــة وحلفــت اليمــن‪ -‬جــرى الكتابــة لهيئــة النظــر لتقديــر‬\n      ‫نفقــة املدعيــة عــن املــدة املدعــى بهــا‪ -‬يف جلســة أخــرى حضــرت املدعيــة‬\n      ‫برفقــة والدهــا ولــم يحضــر املدعــى عليــه وقــررت املدعيــة أنهــا تطلــب‬\n      ‫تأجيــل النظــر يف دعــوى النفقــه وأنهــا ســوف تقيمهــا بدعــوى مســتقلة‬\n      ‫وطلبــت احلكــم بقيمــة الذهــب وقيمــة فاتــورة الهاتــف‪ -‬صــدر احلكــم‬\n      ‫علــى املدعــى عليــه بدفــع قيمــة الذهــب وذكــر قــدره وفاتــورة الهاتــف‬\n      ‫الثابــت وذكــر قدرهــا كمــا ثبــت لــدى القاضــي تأجيــل املدعيــة لدعــوى‬\n      ‫النفقــه‪ -‬قنعــت املدعيــة باحلكــم وســيجرى تبليغ املدعــى عليه باحلكم‪-‬‬\n                                       ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32225389‬وتاريــخ ‪1432/06/13‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32702424‬وتاريــخ ‪1432/06/13‬ه ـ وفيهــا حضــر ‪...‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيــا عــن‬\n      ‫ابنتــه‪ ...‬ســعودية مبوجــب الســجل املدنــي رقــم ‪ ...‬ولــم يحضــر وكالــة‬\n‫‪171‬‬\n\f‫عنهــا وقــال‪ :‬ســأحضر وكالــة عنهــا يف اجللســة القادمــة وادعــى علــى‬\n‫احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬قائــا‬\n‫يف دعــواه ‪ :‬إن موكلتــي زوجــة للمدعــى عليــه ولــم تنجــب منــه شــيئ ًا ثــم‬\n‫قــام بإحضارهــا يف ‪1431/10/01‬ه ـ وتركهــا عنــد أهلهــا حتــى صــدور‬\n‫احلكــم بفســخ نكاحهــا يف ‪1433/02/02‬ه ـ لــذا أطلــب مــا يلــي ‪-1‬‬\n‫نفقتهــا مــدة ســنة وأربعــة أشــهر اعتبــار ًا مــن ‪1431/10/01‬ه ـ وحتــى‬\n‫تاريــخ طالقهــا ‪ -2‬قيمــة الذهــب الــذي أخــذه منهــا وأقــر بــه املدعــى‬\n‫عليــه يف احلكــم ‪ -3‬قيمــة فاتــورة هاتــف ثابــت وقدرهــا ثمامنائــة ريــال‬\n‫ا ماذكــره‬     ‫هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n‫بفســخ نكاحــي منهــا صحيــح ومــا ذكــره مــن النفقــة فغيــر صحيــح فقد‬\n‫ذهبــت بهــا عنــد أهلهــا يف ‪1431/10/01‬ه ـ وعندمــا أردت أخذهــا قالــت‬\n‫أختــي ســوف تذهــب معــي فرفضــت الذهــاب معــي وعليــه فــا نفقــة لهــا‬\n‫ألنهــا ناشــز وأمــا الذهــب فهــو عطيــة منهــا كمــا يحصــل بــن األزواج‬\n‫وأمــا فاتــورة الهاتــف فــا عالقــة لــي بهــا وهــي التــي تســتعمله وهــي التــي‬\n‫قامــت بتركيبــه باســمها يف منزلــي وأطلــب رد دعواهــا وبعرضــه علــى‬\n‫املدعــي قــال الصحيــح مــا جــاء يف دعــواي ثــم أبــرز لنــا صــورة مــن احلكــم‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 3359746‬يف ‪1433/02/02‬ه ـ‬\n‫املتضمــن احلكــم بفســخ نــكاح املدعيــة مــن املدعــى عليــه علــى عــوض‬\n‫وقــد جــاء فيــه إقــراره بأخــذه مــن الذهــب مــا قيمتــه عشــرة آالف ريــال‬\n‫فبنــاء علــى مــا قــرره الفقهــاء أن الزوجــن إذا أختلفــا يف النشــوز فالقــول‬\n‫قولهــا مــع ميينهــا ( الشــرح الكبيــر ( ‪ ) 262/6‬فقــال ‪ :‬أطلــب ميينهــا علــى‬\n‫عــدم النشــوز وعلــى فاتــورة الهاتــف فأجيــب لطلبــه ورفعــت اجللســة مــن‬\n              ‫أجــل إحضــار املدعــي وكالــة عــن ابنتــه أو حضورهــا أصالــة‬\n\n\n                                                                                       ‫‪172‬‬\n\f      ‫ويف جلســة أخــرى حضــر الطرفــان وقــررت املدعيــة بقولهــا إن املدعــى‬\n      ‫عليــه قــد طلــب منــي الرجــوع معــه ونحــن يف مدينــة الباحــة والســكن‬\n      ‫مــع أهلــه فرفضــت الرجــوع وبعدهــا لــم يطلــب منــي الرجــوع إلــى بيــت‬\n      ‫الزوجيــة ولــم أرفــض ذلــك وأنــا مســتعدة علــى بــذل اليمــن علــى ماطلبــه‬\n      ‫املدعــى عليــه ثــم تلفظــت بقولهــا واهلل العظيــم أننــي لــم أرفــض الرجــوع‬\n      ‫مــع املدعــى عليــه إلــى بيــت الزوجيــة وأن املدعــى عليــه قــد اســتخرج‬\n      ‫الهاتــف الثابــت باســمي وقمــت باســتعماله أنــا واملدعــى عليــه ســويا وأن‬\n      ‫قيمــة فاتورتــه ثمامنائــة ريــال هكــذا حلفــت وبعرضــه علــى املدعــى عليــه‬\n      ‫قــال إننــي غيــر قانــع بيمينهــا لــذا فقــد قــررت الكتابــة لهيئــة النظــر‬\n      ‫يف احملكمــة لتقديــر نفقــة املدعيــة املاضيــة ورفعــت اجللســة لذلــك ويف‬\n      ‫جلســة أخــرى حضــرت املدعيــة ‪ ...‬املعــرف بهــا مــن قبــل أبيهــا ‪ ...‬ولــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه بوكالــة شــرعية ولــم تردنــا‬\n      ‫إفــادة مــن قســم اخلبــراء وقالــت املدعيــة‪ :‬إننــي لــم أراجــع قســم اخلبــراء‬\n      ‫ولــم يطلــب منــي ثــم قــررت بقولهــا‪ :‬إننــي أطلــب تأجيــل النظــر يف دعــوى‬\n      ‫النفقــة وســوف أقيمهــا بدعــوى مســتقلة وأطلــب احلكــم بقيمــة الذهــب‬\n                                                               ‫وقيمــة فاتــورة الهاتــف ‪.‬‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى‬\n      ‫عليــه بــأن يف ذمتــه للمدعيــة مبلــغ عشــرة آالف ريــال قيمــة ذهــب ومبــا أن‬\n      ‫املدعيــة بذلــت ميينهــا علــى أن املدعــي اســتخرج الهاتــف الثابــت باســمها‬\n      ‫وقبــل املدعــي ميينهــا لــذا فقــد حكمــت علــى املدعــى عليــه بدفــع قيمــة‬\n      ‫الذهــب وقــدره عشــرة آالف ريــال وفاتــورة الهاتــف الثابــت وقدرهــا‬\n      ‫ثمامنائــة ريــال كمــا ثبــت لــدي تأجيــل املدعيــة لدعــوى النفقــة وبعــرض‬\n      ‫احلكــم عليهــا قــررت قناعتهــا باحلكــم وســيجري تبليــغ املدعــى عليــه‬\n\n\n‫‪173‬‬\n\f‫باحلكــم حســب التعليمــات وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/12/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة بالريــاض‬\n‫خلــف فضيلــة الشــيخ‪...‬مبوجب كتــاب رئيــس احملكمــة العامــة‬\n‫بالريــاض ذي الرقــم ‪ 34/1590732‬والتاريــخ ‪1434/07/02‬ه ـ جــرى‬\n‫فتــح اجللســة لعــودة املعاملــة مــن محكمــة االســتئناف بالريــاض مصادقـ ًا‬\n‫عليهــا بالقــرار ذي الرقــم ‪ 34269552‬والتاريــخ ‪1434/07/16‬ه ـ مــن‬\n‫أصحــاب الفضيلــة قضــاة الدائــرة الثانيــة لتمييــز قضايــا األحــوال‬\n‫الشــخصية واإلنهــاءات وهــم قاضــي االســتئناف ‪ ...‬وقاضــي االســتئناف‬\n‫‪ ...‬ورئيــس الدائــرة ‪ ...‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمد‬\n                                                    ‫حــرر يف ‪1434/09/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض برقــم‪ 32702424‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املســجل برقــم‬\n‫‪ 33473430‬وتاريــخ ‪1433/12/20‬ه ـ اخلــاص بدعــوى‪ ... /‬ضــد‪ ... /‬يف‬\n‫مبلــغ مالــي علــى الصفــة املوضحــة بالصــك ‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مباهــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n               ‫وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪174‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":170,"source_page_end":174,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3dbdb93a74b673d6283e67dd82e180203cebc9a156469032eb2ba96343e02179","normalized_text_hash":"f881b95e7fc17378906f134eaf6dc7ee16700bbc6d2db43c545b0ad5e7497586","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p170-33473430"},{"id":"6aaa1285-dc90-5c8a-90e0-bf720ab94afa","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة الزوجة وأوالدها القصر والبالغن -خروج الزوجة بعد قذف زوجها اليعد نشوز ا -احلكم بنفقة للزوجة واألوالد القصر والبالغن -مشمولة بالنفاذ املعجل بكفالة.","document_number":"34166629","case_number":"33492272","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"نفقة -نفقة الزوجة وأوالدها القصر والبالغن -خروج الزوجة بعد قذف زوجها اليعد نشوز ا -احلكم بنفقة للزوجة واألوالد القصر والبالغن -مشمولة بالنفاذ املعجل بكفالة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/13 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34166629 :‬‬\n                          ‫َر ْق ُم الدعوى‪33492272 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34196790‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬نفقــة الزوجــة وأوالدهــا القصــر والبالغــن ‪ -‬خــروج الزوجــة بعد‬\n      ‫قــذف زوجهــا اليعــد نشــوز ًا ‪ -‬احلكــم بنفقــة للزوجــة واألوالد القصــر‬\n                              ‫والبالغــن‪ -‬مشــمولة بالنفــاذ املعجــل بكفالــة‪.‬‬\n\n\n\n\n                                               ‫املادة ‪ 199‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة أصالــة عــن نفســها وبالوكالــة عــن ثــاث مــن بناتهــا ضــد‬\n      ‫زوجهــا بأنهــا رزقــت منــه بخمســة أوالد اثنــان قاصــران والباقــي وهــم‬\n      ‫موكالهــا البالغــان وذكــرت املدعيــة أنهــا خرجــت مــن بيــت زوجهــا‬\n      ‫بعــد قذفهــا وهــي تطالــب بنفقتهــا ونفقــة أوالدهــا اخلمســة ‪ -‬أجــاب‬\n      ‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أنــه لــن ينفــق علــى الزوجــة‬\n      ‫حتــى تعــود املدعيــة إلــى بيــت الزوجيــة ‪ -‬قــرر القاضــي أن خــروج الزوجة‬\n      ‫بعــد قــذف الــزوج لهــا ال يعــد نشــوز ًا ‪ -‬ومت تقديــر نفقــة األم وأوالدهــا‬\n      ‫مبلغ ـ ًا قــدره مائتــان وأربعــة وثمانــون ريــا ًال لــكل واحــد منهــم ‪ -‬قــرر‬\n      ‫ناظــر القضيــة نظــر ًا ألن قــذف املدعــى عليــه لزوجتــه يعتبــر مبــرر ًا‬\n      ‫خلروجهــا فقــد صــدر احلكــم بإلــزام املدعــى عليــه بتســليم املدعيــة لهــا‬\n\n‫‪175‬‬\n\f‫وألوالدهــا القاصريــن نفقــة شــهرية قدرهــا مائتــان وأربعــة وثمانــون ريــا ًال‬\n‫لــكل واحــد وأن يســلم لبناتــه الثــاث البالغــات لــكل واحــدة منهــن‬\n‫مبلغـ ًا وقــدره مائتــان وأربعــة وثمانــون ريــا ًال وقــرر شــمول احلكــم بالنفــاذ‬\n‫املعجــل بكفالــة ‪ -‬اعتــرض املدعــى عليــه علــى احلكــم ‪ -‬صــدر قــرار‬\n                                 ‫محكمــة االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالرياض‬\n‫ففــي يــوم األحــد املوافــق‪ 1433/08/11‬ه ـ حضــرت ‪ ........‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬وادعــت علــى احلاضــر معهــا‬\n‫‪ ........‬حامــل الســجل املدنــي رقــم‪ :........‬قائلــة يف دعواهــا‪ :‬إن املدعــى‬\n‫عليــه زوجــي وقــد قذفنــي فخرجــت مــن بيتــه يف ‪1433/7/12‬ه ـ مــع‬\n‫أوالدي منــه ومنهــم القاصــرون املولــود يف ‪1418/9/27‬ه ـ املولــود يف‬\n‫‪1429/12/28‬ه ـ واملولــودة يف ‪1421/11/7‬ه ـ وهــم يف حضانتــي حاليــا‬\n‫وأطلــب تقديــر نفقــة شــهرية لــي وألوالدي القصــر املذكوريــن وإلــزام‬\n‫املدعــى عليــه بتســليمها لــي هــذه دعــواي‪ .‬وباســتجواب املدعــى عليــه‪،‬‬\n‫قــال‪ :‬مــا ذكرتــه املدعيــة مــن أننــي زوجهــا وأننــي قذفتهــا فخرجــت‬\n‫مــن بيتــي يف ‪1433/7/12‬ه ـ وأننــي لــم أنفــق عليهــا وال علــى األوالد‬\n‫املذكوريــن مــن ذلــك التاريــخ فصحيــح‪ ،‬ولــن أنفــق عليهــا حتــى تعــود‬\n‫إلــى بيتــي وأمــا األوالد املذكوريــن فليســوا أوالدي‪ ،‬وقــد حملــت بهــم‬\n‫املدعيــة مــن غيــري لــذا فلــن أنفــق عليهــم‪ ،‬وقــد أقمــت دعــوى لــدى‬\n‫الشــيخ بخصــوص نفــي بعــض األوالد ومنهــم املذكــورون يف الدعــوى‪،‬‬\n‫وقــد حــدد موعــد اجللســة يف ‪1434/2/19‬ه ـ هكــذا أجــاب‪ .‬وبعــرض‬\n                                                                                         ‫‪176‬‬\n\f      ‫ذلــك علــى املدعيــة قالــت‪ :‬مــا ذكــره املدعــى عليــه غيــر صحيــح واألوالد‬\n      ‫املذكوريــن أوالده‪ ،‬وقــد أضافهــم يف دفتــر عائلتــه ولــم يشــكك يف‬\n      ‫نســبتهم إليــه إال قبــل ســنة هكــذا أجابــت وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه‪ ،‬قــال‪ :‬إننــي قــد أضفــت األوالد املذكوريــن يف دفتــر عائلتــي‪،‬‬\n      ‫ولكــن طــرأت علــي الشــكوك بعــد ذلــك‪ ،‬هكــذا أجــاب‪ .‬فقــررت‬\n      ‫الكتابــة لقســم اخلبــراء لتقديــر نفقــة شــهرية لــأوالد املذكوريــن‬\n      ‫يف الدعــوى ‪ .‬ويف يــوم اإلثنــن املوافــق‪ 1433/11/22‬ه ـ حضــرت‬\n      ‫املدعيــة‪ ،‬واملدعــى عليــه‪ ،‬وقــد وردنــي قــرار قســم الصلــح رقــم‪661 :‬‬\n      ‫يف ‪1433/8/24‬هـ ـ واملتضمــن ‪« :‬أنــه مت االجتمــاع بالطرفــن ومحاولــة‬\n      ‫االصــاح بينهمــا إال أننــا لــم نتوصــل إلــى حــل ينهــي النــزاع القائــم‬\n      ‫بينهمــا‪ ،‬وقــد قــرر املدعــى عليــه بأنــه ليــس لديــه اســتعداد بدفــع نفقــة‬\n      ‫شــهرية لــأوالد‪ ،‬أمــا املدعيــة فقــد ذكــرت أنهــا مصــرة علــى طلــب‬\n      ‫النفقــة وأنــه تكلفهــا النفقــة مــع االيجــار خمســة آالف ريــال‪ .‬هــذا مــا‬\n      ‫جــاء يف إقرارهمــا املرفــق بطــي املعاملــة‪ ،‬والــذي نــراه أن يلــزم املدعــى‬\n      ‫عليــه إن كان لــه ضمــان لــأوالد بتســليمه للمدعيــة‪ ،‬وإن لــم يكــن لــه‬\n      ‫ضمــان فقــد قدرنــا لــكل واحــد منهــم ثالثمئــة ريــال‪ ،‬وهــذا أدنــى وأقــل‬\n      ‫الكفاية»ا‪.‬هـ ـ فســألت املدعــى عليــه‪ ،‬هــل اســتلم ضمانــا يخــص أوالده‬\n      ‫املذكوريــن يف الدعــوى؟ فقــال‪ :‬نعــم‪ ،‬وال أدري عــن نصيــب كل واحــد‬\n      ‫منهــم‪ ،‬فقــررت الكتابــة للضمــان االجتماعــي لإلفــادة عــن نصيــب كل‬\n                                                    ‫واحــد مــن أوالد املدعــى عليــه ‪.‬‬\n      ‫ويف يــوم اإلثنــن املوافق‪1434/03/16‬ه ـ حضــرت املدعيــة املعــرف بهــا‬\n      ‫مــن قبــل أخيهــا ‪ ...‬ســعودي بالســجل رقــم واملدعــى عليــه وقــد وردنــي‬\n      ‫خطــاب مديــر عــام مكتــب الضمــان االجتماعــي مبنطقــة الريــاض‬\n\n\n‫‪177‬‬\n\f‫برقــم ‪ 5397‬يف ‪1433/12/26‬ه ـ وقــد جــاء فيــه مــا نصــه ‪ ( :‬أفيدكــم‬\n‫بــأن‪ ...‬يســتلم راتــب ضمــان شــهري قــدره ثالثــة آالف وســبعمائة وثالثــة‬\n‫ريــاالت كالتالــي نصيــب األب ثمامنائــة واثنــان وســتون ريــال ونصيــب‬\n‫كل فــرد مــن العائلــة مبــا فيهــم الزوجــة مائتــان وأربعــة وثمانــون ريــاال‬\n‫وعددهــم عشــرة) وأحضــرت املدعيــة وكالــة من‪...‬و‪..‬و‪...‬بنــات الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 33236272‬يف‬\n‫‪1433/08/19‬ه ـ والتــي تخولهــا حــق املرافعــة واملدافعــة واإلقــرار‬\n‫والصلــح وقبــول األحــكام واالعتــراض عليهــا واســتالم املبالــغ وقالــت‬\n‫إن املدعــى عليــه ال ينفــق علــى موكالتــي وأطلــب تقديــر نفقــة شــهرية‬\n‫لهــن وإلــزام املدعــى عليــه بهــا علمــا أن الصــواب تاريــخ ميــاد ابنــي ‪.........‬‬\n‫هــو ‪1419/12/28‬ه ـ هــذه دعــواي وباســتجواب املدعــى عليــه قــال لــن‬\n‫أنفــق علــى بناتــي املذكــورات وتاريــخ ميــاد ابنــي هــو ‪1419/12/28‬ه ـ‬\n‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا جــاء يف‬\n‫قــرار قســم الصلــح وخطــاب الضمــان االجتماعــي ومبــا أن قــذف املدعــى‬\n‫عليــه للمدعيــة مبــرر خلروجهــا مــن منزلــه وال تعتبــر ناشــزا وبنــاء علــى‬\n‫املــادة التاســعة والتســعني بعــد املائــة مــن نظــام املرافعــات الشــرعية لــذا‬\n‫فقــد حكمــت علــى املدعــى عليــه بــأن يســلم للمدعيــة نفقــة شــهرية لهــا‬\n‫ولولديهــا القاصريــن قدرهــا مائتــان وأربعــة وثمانــون ريــال لــكل واحــد‬\n‫منهــم وأن يســلم ألوالدهــا البالغــن نفقــة شــهرية قدرهــا مائتــان وأربعــة‬\n‫وثمانــون ريــال لــكل واحــد منهــم مــع النفــاذ املعجــل بكفالــة وبعــرض‬\n‫احلكــم علــى الطرفــن قنعــت بــه املدعيــة أمــا املدعــى عليــه فلــم يقنــع‬\n‫بــه وطلــب االســتئناف فأجبتــه لطلبــه وأفهمتــه بــأن عليــه املراجعــة يــوم‬\n‫األحــد املوافــق ‪1434/03/22‬ه ـ الســتالم صــورة مــن صــك احلكــم‬\n\n\n                                                                                          ‫‪178‬‬\n\f      ‫لتقــدمي معارضتــه عليــه خــال مــدة ال تتجــاوز ثالثــن يومــا مــن ذلــك‬\n      ‫التاريــخ فــإن لــم يقــدم معارضتــه خاللهــا ســقط حقــه يف االعتــراض‬\n      ‫واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/05/07‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11:45‬وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالريــاض وقــد همــش علــى ظهــر الصــك مبــا نصــه (‬\n      ‫تظهيــرات الدائــرة الثانيــة لألحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫االســتئناف مبنطقــة الريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا‬\n      ‫علــى هــذا الصــك رقــم ‪ 34166629‬وتاريــخ ‪1434/03/21‬ه ـ الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪ ........‬وأصدرنــا القــرار رقــم ‪ 34196790‬وتاريــخ‬\n      ‫‪1434/04/24‬ه ـ املتضمــن املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n      ‫‪ .‬عضــو ختمــه وتوقيعــه عضــو ختمــه وتوقيعــه رئيــس الدائــرة ختمــه‬\n      ‫وتوقيعــه ‪ ) .‬وكان ختــام هــذه اجللســة الســاعة ‪ 12:00‬وبــاهلل التوفيــق ‪،‬‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/05/07‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331422680‬وتاريــخ ‪1434/4/13‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪...../‬‬\n      ‫املســجل برقــم ‪ 34166629‬وتاريــخ ‪1434/3/21‬ه ـ اخلــاص بدعــوى‪...../‬‬\n      ‫ضــد ‪ ...../‬يف قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه‬\n\n\n‫‪179‬‬\n\f‫مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪-‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪180‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":175,"source_page_end":180,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a537aca8ca71903c3fd1ec28de9b891ad923348519e11402ff0cab2ea52115e","normalized_text_hash":"2b0cdb08329dd44333db669c1678485fcadc9c975a675a3698bf3a97d66e53fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p175-34166629"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

